export const assets = {"/admin.css":{"type":"text/css; charset=utf-8","base64":false,"content":".nav[href]{text-decoration:none;display:block;border-radius:6px}.management-panel{margin-top:0}.admin-stats{display:grid;grid-template-columns:1fr 1fr 1.2fr;gap:18px;margin-bottom:32px}.admin-stats>div{background:#fff;border:1px solid #e2e7ed;border-radius:8px;padding:23px}.admin-stats span{font-size:8px;color:#9b8b71;letter-spacing:1px;display:block}.admin-stats strong{font:30px Georgia;display:block;margin-top:14px;color:#233d51}.admin-stats>div:last-child strong{font:23px Georgia}.admin-section-head{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:24px}.admin-section-head p{font-size:11px;color:#8d99a7;line-height:1.7}.admin-cakes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.admin-cake{background:white;border:1px solid #e2e7ed;border-radius:8px;overflow:hidden;min-width:0}.admin-cake-image{position:relative;aspect-ratio:4/4.3}.admin-cake-image img{width:100%;height:100%;object-fit:cover}.status-pill{position:absolute;top:13px;left:13px;font-size:8px;padding:7px 11px;border-radius:20px;background:#fffdf6e8;color:#718271}.status-pill.draft{color:#a68e73;background:#fff2dce8}.admin-cake-info{padding:19px}.cake-category{font-size:8px;letter-spacing:1px;color:#b19a72;text-transform:uppercase}.admin-cake h3{font:22px Georgia;margin:12px 0;overflow-wrap:anywhere}.admin-cake p{font-size:10px;color:#95a0ad;line-height:1.9;overflow-wrap:anywhere;margin-bottom:18px}.admin-cake-actions{display:flex;flex-wrap:wrap;gap:6px}.admin-cake-actions button{font-size:9px;border:1px solid #e1e4e8;padding:8px 9px;border-radius:4px}.admin-cake-actions button:first-child{background:#203a4d;color:white;border-color:#203a4d}.settings-card{padding:30px;background:#fff;border:1px solid #e2e7ed;border-radius:9px;max-width:690px}.settings-card label{font-size:11px}.settings-note,.settings-message{font-size:11px;line-height:1.8;color:#9d8f77;margin:20px 0}.cake-edit-dialog{width:520px;max-height:90dvh;overflow:auto}.cake-edit-dialog form{margin-top:20px}.photo-upload{background:#f6f3ee;border:1px dashed #d6c7b1;border-radius:6px;padding:18px;text-align:center;position:relative;overflow:hidden;color:#9b8768}.photo-upload img{width:100%;max-height:220px;object-fit:cover;border-radius:4px;margin-bottom:13px}.photo-upload>span{font-size:12px;display:block}.photo-upload input{font-size:10px;padding:8px;background:transparent;border:0;margin:12px auto 0;max-width:270px}.photo-upload small{font-size:9px;color:#b09c80;display:block;margin-top:7px}.cake-checks{padding-top:12px}.cake-checks label{display:flex;align-items:center;gap:6px;font-size:10px;margin:6px 0 15px}.cake-checks input{width:auto;margin:0}.management-error{font-size:11px;line-height:1.8;color:#a0574e;background:#fff1ed;border:1px solid #eed4cd;border-radius:5px;padding:12px}.aside-bottom{font-size:10px}#contactStat{overflow-wrap:anywhere}#cakeEditMessage[hidden]{display:none!important}@media(max-width:1200px){.admin-cakes{grid-template-columns:repeat(2,minmax(0,1fr))}.admin-stats{gap:12px}.admin-stats>div{padding:18px}.admin-stats>div:last-child strong{font-size:20px}}@media(max-width:600px){.admin-stats{grid-template-columns:1fr 1fr;gap:12px}.admin-stats>div:last-child{grid-column:1/-1}.admin-stats strong{font-size:26px}.admin-cakes{grid-template-columns:1fr}.admin-cake-image{aspect-ratio:4/3.7}.admin-section-head{align-items:flex-start}.admin-section-head p{font-size:10px;max-width:210px}.admin-section-head button{white-space:nowrap;font-size:10px}.settings-card{padding:23px}.cake-edit-dialog{padding:23px}}@media print{.management-panel,.cake-edit-dialog{display:none!important}}\n\n.customer-call{color:#203a4d;border:1px solid #e1e4e8;padding:9px 16px;border-radius:5px;text-decoration:none;font-size:12px}#customerSearch{max-width:360px}\n.finance-stats{grid-template-columns:repeat(3,minmax(0,1fr))}.finance-stats strong,.finance-stats>div:last-child strong{font-size:clamp(20px,2.2vw,30px);overflow-wrap:anywhere}.finance-stats>div:first-child{background:#f1f6f0;border-color:#d4dfd1}.finance-table-wrap{overflow-x:auto;border:1px solid #e2e7ed;border-radius:8px;background:white}.finance-table{width:100%;border-collapse:collapse;text-align:left;font-size:12px;min-width:610px}.finance-table th{padding:17px;color:#627084;background:#f4f6f9;font-weight:500}.finance-table td{padding:18px 17px;border-top:1px solid #e2e7ed}.finance-table th:not(:first-child),.finance-table td:not(:first-child){text-align:right}.finance-table small{display:block;color:#627084;margin-top:7px}.finance-table td:last-child span{display:block;color:#627084;margin-bottom:9px}.finance-table button{font-size:10px;padding:7px 9px;white-space:nowrap}@media(max-width:600px){.finance-stats{grid-template-columns:1fr}.finance-stats>div:last-child{grid-column:auto}}\n\n.finance-extra{grid-template-columns:1fr 1fr}.finance-extra>div:last-child strong{font:30px Georgia;overflow-wrap:anywhere}.expense-section{margin:32px 0;padding:26px;background:#fff;border:1px solid #e2e7ed;border-radius:8px}.expense-form fieldset{border:0;padding:0;margin:0;display:grid;grid-template-columns:2fr 1fr;gap:18px}.expense-form label{font-size:12px}.expense-actions{display:flex;gap:10px;grid-column:1/-1}.expense-form p{font-size:12px;color:#627084;line-height:1.7}.expense-record{gap:18px;padding-left:0;padding-right:0}.expense-record strong{overflow-wrap:anywhere}.expense-record>div:last-child{display:flex;gap:8px}.payments-heading{margin:30px 0 20px}@media(max-width:600px){.finance-extra{grid-template-columns:1fr}.finance-extra>div:last-child{grid-column:auto}.expense-section{padding:18px}.expense-form fieldset{grid-template-columns:1fr}.expense-record{flex-wrap:wrap}}\r\n\n.cost-example{padding:18px 22px;border:1px solid #e6d9bd;border-radius:8px;background:#fff9eb;color:#775f35;font-size:13px;line-height:1.7}.cost-layout{display:grid;grid-template-columns:minmax(260px,0.85fr) minmax(330px,1.35fr);gap:24px;align-items:start;margin:24px 0}.cost-card{padding:27px;background:white;border:1px solid #e2e7ed;border-radius:8px;min-width:0}.cost-card h2{font-size:24px;margin:0 0 20px}.cost-card fieldset{border:0;margin:0;padding:0}.cost-card label{font-size:12px}.cost-card select{width:100%;background:#fff;border:1px solid #dbe1e9;border-radius:5px;padding:13px 10px;margin-top:8px;color:#10243d;font:inherit}.ingredient-record{display:flex;gap:12px;align-items:center;justify-content:space-between;border-top:1px solid #e2e7ed;padding:17px 0;font-size:12px;overflow-wrap:anywhere}.ingredient-record small,.saved-cost small{display:block;color:#627084;margin-top:7px;font-size:11px;line-height:1.7}.ingredient-record>div:last-child{display:flex;gap:6px}.ingredient-record button,.cost-line-bottom button{padding:7px;border:1px solid #e2e7ed;border-radius:4px;font-size:10px}.cost-line{background:#f5f7fa;border:1px solid #e2e7ed;border-radius:7px;padding:17px;margin:18px 0}.cost-quantity{display:grid;grid-template-columns:1fr 1fr;gap:15px}.cost-line-bottom{display:flex;gap:10px;align-items:center;flex-wrap:wrap;font-size:12px}.cost-line-bottom small{font-size:10px;color:#627084;flex:1}.cost-line-bottom strong{white-space:nowrap}.cake-cost-total{display:flex;align-items:center;justify-content:space-between;gap:15px;background:#f7efdc;border-radius:6px;padding:22px;margin:22px 0;color:#203a4d}.cake-cost-total span{font-size:10px;letter-spacing:1px}.cake-cost-total strong{font:28px Georgia}.saved-cost{border-top:1px solid #e2e7ed;padding:18px 0}.saved-cost>summary{display:flex;justify-content:space-between;align-items:center;gap:15px;cursor:pointer;font-size:13px}.saved-cost-lines{padding-top:18px}.saved-cost-lines>div{display:flex;justify-content:space-between;gap:20px;padding:13px 0;border-bottom:1px solid #eef0f4;font-size:12px}.saved-cost-lines>button{margin-top:18px}.saved-cost-lines strong{white-space:nowrap}@media(max-width:1000px){.cost-layout{grid-template-columns:1fr}}@media(max-width:600px){.cost-card{padding:20px}.cost-example{font-size:12px}.ingredient-record{flex-wrap:wrap}.saved-cost>summary{align-items:flex-start}.cake-cost-total strong{font-size:24px}}\r\n\n.money-switch{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:28px;padding-bottom:20px;border-bottom:1px solid #e2e7ed}.money-switch button.active{background:#203a4d;color:#fff;border-color:#203a4d}\r\n\n.cost-line-compact{display:flex;align-items:center;gap:14px;padding:15px 17px;background:#fff}.cost-line-compact .cost-line-name{flex:1;min-width:0;overflow-wrap:anywhere;font-size:12px}.cost-line-compact>strong:not(.cost-line-name){white-space:nowrap;font-size:13px}.cost-compact-actions{display:flex;gap:6px}.cost-compact-actions button{padding:6px 8px;font-size:10px;border:1px solid #dbe1e9;border-radius:4px}.cost-line-bottom button[data-finish-cost]{background:#203a4d;color:#fff;border-color:#203a4d}@media(max-width:600px){.cost-line-compact{flex-wrap:wrap;gap:12px}.cost-compact-actions{margin-left:auto}}\r\n\n.one-by-one-picker{margin-bottom:24px;max-width:720px}.one-by-one-picker label{font-size:12px}.one-by-one-picker .settings-note{margin-bottom:0}.profit-stats{grid-template-columns:repeat(3,minmax(0,1fr));margin-top:24px}.profit-stats strong,.profit-stats>div:last-child strong{font:clamp(22px,2.4vw,32px) Georgia;overflow-wrap:anywhere}.profit-result[data-result=profit]{background:#f0f6ee;border-color:#cbdcc5}.profit-result[data-result=loss]{background:#fff1ed;border-color:#eccdc2}#profitMissing p{font-size:13px;line-height:1.8;margin-bottom:20px}#profitBreakdown small{display:block;margin-top:7px;color:#627084;font-size:11px}@media(max-width:600px){.profit-stats{grid-template-columns:1fr}.profit-stats>div:last-child{grid-column:auto}}\r\n\n.profit-cake-card{margin-bottom:22px}.profit-card-heading{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.profit-card-heading h2{margin-bottom:10px}.profit-card-heading strong{font-size:13px;overflow-wrap:anywhere}.profit-card-heading p,.profit-card-heading>span{font-size:12px;color:#627084;line-height:1.8}.profit-card-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:22px 0}.profit-card-stats>div{padding:19px;background:#f4f6f9;border:1px solid #e2e7ed;border-radius:6px;min-width:0}.profit-card-stats span{font-size:9px;letter-spacing:0.5px;color:#627084;display:block}.profit-card-stats strong{display:block;font:clamp(22px,2.2vw,30px) Georgia;margin-top:14px;overflow-wrap:anywhere}.profit-card-stats .profit-result[data-result=profit]{background:#f0f6ee}.profit-card-stats .profit-result[data-result=loss]{background:#fff1ed}.profit-card-details{border-top:1px solid #e2e7ed;margin-top:22px;padding-top:20px}.profit-card-details h3{font-size:15px}.profit-card-details small{display:block;color:#627084;font-size:11px;margin-top:7px}@media(max-width:600px){.profit-card-stats{grid-template-columns:1fr;gap:10px}.profit-card-heading{flex-wrap:wrap}.profit-card-stats>div{display:flex;align-items:center;justify-content:space-between;gap:16px}.profit-card-stats strong{margin-top:0;font-size:24px}}\r\n\n.nav-icon{display:inline-block;vertical-align:-2px;margin-right:12px;flex-shrink:0}\r\n"},"/admin.js":{"type":"text/javascript; charset=utf-8","base64":false,"content":"let galleryItems=[],shopConfig={},shopRevision=0,editingCake=null,uploadBusy=false;\nfunction managementPanel(name){document.querySelectorAll('.management-panel').forEach(p=>p.hidden=true);$('#editor').hidden=true;$('#history').hidden=true;document.querySelectorAll('.nav').forEach(n=>n.classList.remove('active'));$('#'+name+'Panel').hidden=false;$('#'+name+'Tab').classList.add('active');$('#adminTitle').textContent=name==='gallery'?'Your cake gallery.':'Make it your own.';$('#adminSubtitle').textContent=name==='gallery'?'A beautiful little window into your work.':'Your shop details, your words, your website.';$('#new').hidden=true}\nfunction showAdminError(message){$('#galleryAdminError').textContent=message;$('#galleryAdminError').hidden=!message}\nasync function loadGalleryAdmin(){const [g,s]=await Promise.all([api('/api/admin/gallery'),api('/api/admin/settings')]);galleryItems=g.cakes;shopConfig=s.settings;shopRevision=s.revision;renderGalleryAdmin();const f=$('#shopSettingsForm');for(const [key,value]of Object.entries(shopConfig))if(f.elements[key])f.elements[key].value=value;$('#contactStat').textContent=shopConfig.phone;$('#invoiceStat').textContent=records.length;showAdminError('')}\nfunction renderGalleryAdmin(){$('#visibleCakes').textContent=galleryItems.filter(p=>p.active).length;$('#adminCakes').innerHTML=galleryItems.length?galleryItems.map(c=>`<article class=\"admin-cake\"><div class=\"admin-cake-image\"><img src=\"${esc(c.image)}\" alt=\"${esc(c.name)}\" loading=\"lazy\"><span class=\"status-pill ${c.active?'published':'draft'}\">${c.active?'On website':'Hidden'}</span></div><div class=\"admin-cake-info\"><span class=\"cake-category\">${esc(c.category)}</span><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><div class=\"admin-cake-actions\"><button data-edit-cake=\"${esc(c.id)}\">Edit details</button><button data-toggle-cake=\"${esc(c.id)}\">${c.active?'Hide':'Publish'}</button><button data-invoice-cake=\"${esc(c.id)}\">Invoice ↗</button></div></div></article>`).join(''):'<div class=\"empty\">Add your first cake photo to start your gallery.</div>';$('#cakeCategories').innerHTML=[...new Set(galleryItems.map(c=>c.category))].map(c=>`<option value=\"${esc(c)}\"></option>`).join('')}\nfunction editCake(cake){editingCake=cake?JSON.parse(JSON.stringify(cake)):{id:crypto.randomUUID(),name:'',description:'',category:'Celebration cakes',image:'',active:true,featured:false,sortOrder:galleryItems.length*10+10,revision:0};const f=$('#cakeEditForm');for(const key of ['name','description','category','sortOrder'])f.elements[key].value=editingCake[key];for(const key of ['active','featured'])f.elements[key].checked=editingCake[key];$('#cakeDialogTitle').textContent=cake?'Edit cake':'Add a cake';$('#cakeEditMessage').hidden=true;$('#cakeImageFile').value='';updatePhotoPreview();$('#cakeEditDialog').showModal()}\nfunction updatePhotoPreview(){const image=$('#cakeImagePreview');image.hidden=!editingCake.image;image.src=editingCake.image||'';$('#uploadHint').textContent=editingCake.image?'Change photo':'＋ Upload a cake photo'}\n$('#galleryTab').onclick=async()=>{managementPanel('gallery');try{await loadGalleryAdmin()}catch(error){showAdminError(error.message)}};$('#settingsTab').onclick=async()=>{managementPanel('settings');try{await loadGalleryAdmin()}catch(error){$('#settingsMessage').textContent=error.message}};$('#newCake').onclick=()=>editCake(null);$('#closeCakeEdit').onclick=()=>$('#cakeEditDialog').close();\n$('#cakeImageFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){$('#cakeEditMessage').textContent='Choose a JPG, PNG or WebP image smaller than 5 MB.';$('#cakeEditMessage').hidden=false;return}uploadBusy=true;$('#saveCake').disabled=true;$('#uploadHint').textContent='Uploading photo…';try{const r=await fetch('/api/admin/images',{method:'POST',headers:{'Content-Type':file.type},body:file}),data=await r.json();if(!r.ok)throw Error(data.error||'Upload failed.');editingCake.image=data.url;$('#cakeEditMessage').hidden=true;updatePhotoPreview()}catch(error){$('#cakeEditMessage').textContent=error.message;$('#cakeEditMessage').hidden=false;$('#uploadHint').textContent='Try another photo'}finally{uploadBusy=false;$('#saveCake').disabled=false}};\n$('#cakeEditForm').onsubmit=async e=>{e.preventDefault();if(uploadBusy)return;const f=e.target;const cake={id:editingCake.id,image:editingCake.image,name:f.elements.name.value.trim(),description:f.elements.description.value,category:f.elements.category.value.trim(),sortOrder:Number(f.elements.sortOrder.value),active:f.elements.active.checked,featured:f.elements.featured.checked};if(!cake.image){$('#cakeEditMessage').textContent='Upload a cake photo first.';$('#cakeEditMessage').hidden=false;return}$('#saveCake').disabled=true;try{await api('/api/admin/gallery/'+cake.id,{method:'PUT',body:JSON.stringify({cake,revision:editingCake.revision})});$('#cakeEditDialog').close();await loadGalleryAdmin();toast('Cake gallery updated')}catch(error){$('#cakeEditMessage').textContent=error.message;$('#cakeEditMessage').hidden=false}finally{$('#saveCake').disabled=false}};\n$('#adminCakes').onclick=async e=>{const button=e.target.closest('button');if(!button)return;const id=button.dataset.editCake||button.dataset.toggleCake||button.dataset.invoiceCake,cake=galleryItems.find(c=>c.id===id);if(!cake)return;if(button.dataset.editCake)return editCake(cake);if(button.dataset.toggleCake){button.disabled=true;try{const {revision,...p}=cake;await api('/api/admin/gallery/'+id,{method:'PUT',body:JSON.stringify({cake:{...p,active:!p.active},revision})});await loadGalleryAdmin();toast(cake.active?'Cake hidden from website':'Cake published')}catch(error){toast(error.message)}finally{button.disabled=false}}if(button.dataset.invoiceCake){if(dirty&&!confirm('Start an invoice for this cake? Unsaved invoice changes will be replaced.'))return;model=defaults();model.items=[{name:cake.name,detail:cake.category,qty:1,price:0}];model.shop=shopConfig.name.slice(0,24);model.tagline=shopConfig.tagline.slice(0,35);model.phone=shopConfig.phone.slice(0,40);model.email=shopConfig.email.slice(0,65);model.location=shopConfig.location.slice(0,65);dirty=true;bindForm();tab(false);window.scrollTo({top:0,behavior:'smooth'})}};\n$('#shopSettingsForm').onsubmit=async e=>{e.preventDefault();const next=Object.fromEntries(new FormData(e.target));$('#saveSettings').disabled=true;$('#settingsMessage').textContent='';try{const r=await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({settings:next,revision:shopRevision})});shopConfig=next;shopRevision=r.revision;$('#settingsMessage').textContent='Saved. Your public website has been updated.';$('#contactStat').textContent=next.phone;toast('Website settings saved')}catch(error){$('#settingsMessage').textContent=error.message}finally{$('#saveSettings').disabled=false}};\nmanagementPanel('gallery');loadGalleryAdmin().catch(error=>showAdminError(error.message));\n\nlet customerList=[];\nfunction renderCustomers(){const q=$('#customerSearch').value.trim().toLowerCase();const rows=customerList.filter(c=>c.name.toLowerCase().includes(q)||c.phone.includes(q.replace(/[^0-9]/g,''))&&/[0-9]/.test(q));$('#customerCount').textContent=customerList.length;$('#customerRecords').innerHTML=rows.length?rows.map(c=>'<div class=\"record\"><div><strong>'+esc(c.name)+'</strong><small>'+esc(c.phone)+'</small></div><a class=\"customer-call\" href=\"tel:'+esc(c.phone)+'\">Call</a></div>').join(''):'<div class=\"empty\">'+(q?'No matching customers.':'No customers yet. Save an invoice with a customer name and phone number.')+'</div>'}\n$('#customersTab').onclick=async()=>{managementPanel('customers');$('#adminTitle').textContent='Your customers.';$('#adminSubtitle').textContent='Customer contacts saved from your invoices.';$('#customersError').hidden=true;try{await api('/api/customers/sync',{method:'POST',body:'{}'});const data=await api('/api/customers');customerList=data.customers;renderCustomers()}catch(error){$('#customersError').textContent=error.message;$('#customersError').hidden=false}};\n$('#customerSearch').oninput=renderCustomers;\n\napi('/api/customers/sync',{method:'POST',body:'{}'}).then(()=>api('/api/customers')).then(data=>{customerList=data.customers;renderCustomers()}).catch(()=>{});\n\nfunction financeSummary(invoices){\n  return invoices.reduce((s,invoice)=>{const t=totals(invoice);s.received+=Math.round(Number(invoice.advance||0)*100);s.invoiced+=Math.round(t.total*100);s.outstanding+=Math.round(t.balance*100);return s},{received:0,invoiced:0,outstanding:0});\n}\nfunction renderFinance(){\n  const sums=financeSummary(records);\n  $('#moneyReceived').textContent=money(sums.received/100);\n  $('#moneyInvoiced').textContent=money(sums.invoiced/100);\n  $('#moneyOutstanding').textContent=money(sums.outstanding/100);\n  $('#financeRows').innerHTML=records.length?records.map(invoice=>{const t=totals(invoice),paid=Number(invoice.advance||0),status=paid>t.total?'Overpaid':t.balance===0?'Paid':paid>0?'Part paid':'Unpaid';return `<tr><td><strong>${esc(invoice.number)}</strong><small>${esc(invoice.customer)}</small></td><td>${money(t.total)}</td><td>${money(paid)}</td><td>${money(t.balance)}</td><td><span>${status}</span><button class=\"customer-call\" data-payment-invoice=\"${esc(invoice.id)}\">Update payment</button></td></tr>`}).join(''):'<tr><td colspan=\"5\" class=\"empty\">No saved invoices yet.</td></tr>';\n  $('#financeMessage').textContent=records.length+' saved invoice'+(records.length===1?'':'s')+' · All time';\n}\nasync function loadFinance(){\n  $('#financeContent').hidden=true;$('#financeMessage').textContent='Loading saved payments…';$('#refreshFinance').disabled=true;\n  try{await loadRecords();renderFinance();$('#financeContent').hidden=false}catch(error){$('#financeMessage').textContent=error.message}finally{$('#refreshFinance').disabled=false}\n}\nfunction moneySection(view){managementPanel('finance');const costing=view===true||view==='costing',one=view==='one',ingredients=view==='ingredients';$('#moneyOverview').hidden=costing||one||ingredients;$('#ingredientsPanel').hidden=!ingredients;$('#costingPanel').hidden=!costing;$('#oneByOnePanel').hidden=!one;for(const [id,active]of [['moneyOverviewTab',!costing&&!one&&!ingredients],['costingTab',costing],['oneByOneTab',one],['ingredientsTab',ingredients]]){$('#'+id).classList.toggle('active',active);$('#'+id).setAttribute('aria-pressed',String(active))}}\n$('#moneyOverviewTab').onclick=()=>$('#financeTab').onclick();\n$('#financeTab').onclick=async()=>{moneySection(false);$('#adminTitle').textContent='Your money summary.';$('#adminSubtitle').textContent='Received payments and outstanding balances.';await loadFinance()};\n$('#refreshFinance').onclick=loadFinance;\n$('#financeRows').onclick=e=>{const id=e.target.dataset.paymentInvoice;if(!id)return;const invoice=records.find(r=>r.id===id);if(!invoice)return;if(dirty&&!confirm('Open this invoice? Save your current changes first if you want to keep them.'))return;model=JSON.parse(JSON.stringify(invoice));dirty=false;bindForm();tab(false);toast('Update Amount received with the total paid so far, then Save invoice.')};\n"},"/app.js":{"type":"text/javascript; charset=utf-8","base64":false,"content":"const $=s=>document.querySelector(s),KEY='jananee-invoices-v1',DRAFT='jananee-draft-v1';\nconst esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst money=v=>Number(v).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});\nconst today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Colombo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());\nlet records=[],model,dirty=false,versions=new Map(),userEmail='';\nconst defaults=()=>({id:crypto.randomUUID(),number:'JN-'+String(Math.max(0,...records.map(r=>Number(r.number?.match(/\\d+$/)?.[0])||0))+1).padStart(3,'0'),date:today(),customer:'',customerPhone:'',customerDetails:'',shop:'JANANEE',tagline:'CAKE SHOP',phone:'+94 767759606',email:'jcskumara05@gmail.com',location:'Kadawatha',footer1:'We appreciate your support!',footer2:'Hope to serve you again soon.',discount:0,advance:0,note:'',items:[{name:'',detail:'',qty:1,price:0}]});\nfunction toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}\nfunction persistDraft(){} // Drafts remain in memory until explicitly saved to the account.\nfunction totals(m=model){const subtotal=m.items.reduce((s,i)=>s+Math.round(i.qty*i.price*100)/100,0);const total=Math.max(0,subtotal-Number(m.discount));return{subtotal,total,balance:Math.max(0,total-Number(m.advance))}}\nfunction text(x,y,s,size=10,extra=''){return `<text x=\"${x}\" y=\"${y}\" font-size=\"${size}\" ${extra}>${esc(s)}</text>`}\nfunction lines(s,max=42){const out=[];for(const p of String(s).split('\\n')){let row='';for(const w of p.split(' ')){if((row+' '+w).length>max&&row){out.push(row);row=w}else row+=(row?' ':'')+w}out.push(row)}return out}\nfunction render(){const m=model,t=totals();let body='';let y=455;for(const i of m.items){const nl=lines(i.name,36),dl=lines(i.detail,48);const h=Math.max(69,25+nl.length*15+dl.length*12);body+=`<rect x=\"36\" y=\"${y}\" width=\"523.2756\" height=\"${h}\" rx=\"4\" fill=\"#f4f6f9\"/>`;nl.forEach((l,j)=>body+=text(55,y+25+j*15,l,12,'font-weight=\"700\"'));dl.forEach((l,j)=>body+=text(55,y+27+nl.length*15+j*12,l,9,'fill=\"#627084\"'));body+=text(375,y+h/2+4,i.qty,11,'text-anchor=\"middle\"')+text(540,y+h/2+4,money(i.qty*i.price),11,'text-anchor=\"end\"');y+=h+4}\nlet sy=y+42;let sums=`<path d=\"M310 ${sy}H557\" stroke=\"#dde3eb\"/>`+text(318,sy+24,'SUBTOTAL (LKR)')+text(540,sy+24,money(t.subtotal),11,'text-anchor=\"end\"');let ty=sy+62;if(+m.discount){sums+=text(318,ty-10,'DISCOUNT (LKR)')+text(540,ty-10,'− '+money(m.discount),11,'text-anchor=\"end\"');ty+=28} sums+=`<rect x=\"307\" y=\"${ty-19}\" width=\"250\" height=\"43\" rx=\"5\" fill=\"#e9eef6\"/>`+text(320,ty+8,'TOTAL (LKR)',14,'font-weight=\"700\"')+text(540,ty+8,money(t.total),14,'font-weight=\"700\" text-anchor=\"end\"');let end=ty+24;if(+m.advance){sums+=text(318,end+25,'PAID (LKR)')+text(540,end+25,money(m.advance),11,'text-anchor=\"end\"')+text(318,end+50,'BALANCE (LKR)',11,'font-weight=\"700\"')+text(540,end+50,money(t.balance),12,'font-weight=\"700\" text-anchor=\"end\"');if(+m.advance>t.total)sums+=text(318,end+70,'OVERPAID: LKR '+money(m.advance-t.total),9,'fill=\"#627084\"');end+=80}\nlet note='';if(m.note){let ny=Math.max(690,end+30);lines(m.note,75).forEach((l,i)=>note+=text(44,ny+i*14,l,10,'fill=\"#627084\"'));end=ny+lines(m.note,75).length*14}\nconst footerY=Math.max(737,end+65),height=Math.max(841.8898,footerY+105);const heart=(x,y,k=1)=>`<path d=\"M${x} ${y} c${-20*k} ${-11.5*k} ${-8*k} ${-21.5*k} 0 ${-11*k} c${8*k} ${-10.5*k} ${20*k} ${-.5*k} 0 ${11*k}\" fill=\"#dca328\"/>`;\n$('#preview').innerHTML=`<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 595.2756 ${height}\" fill=\"#10243d\" role=\"img\" aria-label=\"Invoice ${esc(m.number)} for ${esc(m.customer)}\"><style>@font-face{font-family:InvoiceSans;src:url('/DejaVuSans.ttf')}@font-face{font-family:InvoiceSans;src:url('/DejaVuSans-Bold.ttf');font-weight:700}@font-face{font-family:InvoiceSerif;src:url('/DejaVuSerif.ttf')}text{font-family:InvoiceSans,Arial,sans-serif} .serif{font-family:InvoiceSerif,Georgia,serif}</style><rect width=\"596\" height=\"${height}\" fill=\"white\"/><circle cx=\"635.2756\" cy=\"-30\" r=\"155\" fill=\"#fff6e1\"/>${heart(196,71.5)}${text(44,106,m.shop,Math.min(39,310/Math.max(m.shop.length,1)*1.3),'class=\"serif\"')}<path d=\"M76 123H134 M266 123H326\" stroke=\"#dca328\" stroke-width=\"1.4\"/>${text(200,128,m.tagline,12,'text-anchor=\"middle\"')}${text(44,177,m.phone)}${text(44,197,m.email)}${text(44,217,m.location)}${text(550,175,'INVOICE',30,'class=\"serif\" text-anchor=\"end\"')}<path d=\"M415 188H549\" stroke=\"#dca328\" stroke-width=\"1.4\"/>${heart(483,204,.5)}${text(44,292,'BILL TO',10,'fill=\"#627084\"')}${lines(m.customer,24).map((l,i)=>text(44,320+i*20,l,15,'font-weight=\"700\"')).join('')}${lines([m.customerPhone,m.customerDetails].filter(Boolean).join('\\n'),32).map((l,i)=>text(44,348+i*13,l,9,'fill=\"#627084\"')).join('')}<path d=\"M290 282V374\" stroke=\"#dee3eb\"/>${text(326,292,'INVOICE NO',10,'fill=\"#627084\"')}${text(326,314,m.number,11)}${text(326,345,'DATE',10,'fill=\"#627084\"')}${text(326,367,m.date,11)}<rect x=\"36\" y=\"413\" width=\"523.2756\" height=\"42\" rx=\"6\" fill=\"#10243d\"/>${text(55,439,'DESCRIPTION',10,'style=\"fill:white\" font-weight=\"700\"')}${text(365,439,'QTY',10,'style=\"fill:white\" font-weight=\"700\"')}${text(540,439,'AMOUNT (LKR)',10,'style=\"fill:white\" font-weight=\"700\" text-anchor=\"end\"')}${body}${sums}${note}${text(44,footerY,'Thank You!',29,'class=\"serif\"')}${heart(233,footerY-5,.6)}${text(44,footerY+27,m.footer1,10,'fill=\"#627084\"')}${text(44,footerY+44,m.footer2,10,'fill=\"#627084\"')}<path d=\"M0 ${height}V${height-35}C140 ${height-95} 280 ${height-10} 420 ${height-43}C505 ${height-65} 550 ${height-55} 595 ${height-70}V${height}Z\" fill=\"#fff2d4\"/><path d=\"M0 ${height}V${height-15}C160 ${height-68} 295 ${height+2} 425 ${height-23}C510 ${height-45} 555 ${height-32} 595 ${height-43}V${height}Z\" fill=\"#ffe4a3\"/></svg>`;\n$('#count').textContent=records.length;$('#state').textContent=dirty?'Unsaved changes · save to your account':'Ready to edit';persistDraft()}\nfunction bindForm(){document.querySelectorAll('[data-field]').forEach(e=>e.value=model[e.dataset.field]??'');renderItems();render()}\nfunction renderItems(){$('#items').innerHTML=model.items.map((i,n)=>`<div class=\"item\"><div class=\"item-top\"><strong>ITEM ${String(n+1).padStart(2,'0')}</strong><button class=\"remove\" data-remove=\"${n}\" aria-label=\"Remove item ${n+1}\">Remove ×</button></div><label>Item name<input data-item=\"${n}\" data-prop=\"name\" value=\"${esc(i.name)}\" maxlength=\"100\" required></label><label>Description<input data-item=\"${n}\" data-prop=\"detail\" value=\"${esc(i.detail)}\" maxlength=\"150\"></label><div class=\"grid\"><label>Quantity<input data-item=\"${n}\" data-prop=\"qty\" type=\"number\" min=\"0.01\" step=\"0.01\" value=\"${i.qty}\" required></label><label>Unit price (LKR)<input data-item=\"${n}\" data-prop=\"price\" type=\"number\" min=\"0\" step=\"0.01\" value=\"${i.price}\" required></label></div></div>`).join('')}\ndocument.addEventListener('input',e=>{const a=e.target;if(a.dataset.field){model[a.dataset.field]=a.type==='number'?Math.max(0,+a.value||0):a.value;dirty=true;render()}if(a.dataset.item!==undefined){model.items[+a.dataset.item][a.dataset.prop]=a.type==='number'?Math.max(0,+a.value||0):a.value;dirty=true;render()}});\n$('#items').onclick=e=>{if(e.target.dataset.remove!==undefined){if(model.items.length===1)return toast('Keep at least one item.');model.items.splice(+e.target.dataset.remove,1);dirty=true;renderItems();render()}};\n$('#add').onclick=()=>{if(model.items.length>=10)return toast('Maximum 10 items per invoice.');model.items.push({name:'',detail:'',qty:1,price:0});dirty=true;renderItems();render()};\nfunction valid(){for(const e of document.querySelectorAll('#editor input'))if(!e.reportValidity())return false;return true}\nasync function api(path,options={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});let data;try{data=await response.json()}catch{throw Error('The server could not be reached. Try again.')}if(response.status===401&&path!=='/api/auth/password'){$('#signinAgain').hidden=false;toast('Session expired. Export your draft backup, then select Sign in again.');throw Error(data.error||'Please sign in again.')}if(!response.ok)throw Error(data.error||'Unable to complete the request.');return data}\nasync function loadRecords(){const data=await api('/api/invoices');records=data.invoices.map(r=>r.invoice);versions=new Map(data.invoices.map(r=>[r.invoice.id,r.revision]));userEmail=data.email;$('#accountEmail').textContent=userEmail;$('#count').textContent=records.length;return records}\nasync function uploadInvoice(invoice){const result=await api('/api/invoices/'+encodeURIComponent(invoice.id),{method:'PUT',body:JSON.stringify({invoice,revision:versions.get(invoice.id)||0})});versions.set(invoice.id,result.revision);return invoice}\nasync function save(){if(!valid())return false;if(records.some(r=>r.number===model.number&&r.id!==model.id)){toast('Invoice number already exists. Use a unique number.');return false}const copy=JSON.parse(JSON.stringify(model));$('#save').disabled=true;try{await uploadInvoice(copy);const idx=records.findIndex(r=>r.id===copy.id);if(idx>=0)records[idx]=copy;else records.unshift(copy);dirty=JSON.stringify(model)!==JSON.stringify(copy);if(!dirty){model=defaults();bindForm();document.title='JANANEE ? Invoice Studio';toast(copy.number+' saved. Ready for '+model.number);}else{render();toast(copy.number+' saved. Your latest changes still need saving.');}return true}catch(e){toast(e.message);return false}finally{$('#save').disabled=false}}\n$('#save').onclick=save;$('#print').onclick=async()=>{if(!valid())return;await document.fonts.ready;document.title=model.number+' · '+model.customer+' · JANANEE';window.print()};\nfunction tab(history){document.querySelectorAll('.management-panel').forEach(e=>e.hidden=true);$('#ingredientsTab').classList.remove('active');$('#oneByOneTab').classList.remove('active');$('#costingTab').classList.remove('active');$('#financeTab').classList.remove('active');$('#customersTab').classList.remove('active');$('#galleryTab').classList.remove('active');$('#settingsTab').classList.remove('active');$('#adminTitle').textContent=history?'Saved invoices.':'Your invoice, beautifully made.';$('#adminSubtitle').textContent='The original JANANEE invoice design, ready for your next customer.';$('#new').hidden=false;$('#editor').hidden=history;$('#history').hidden=!history;$('#historyTab').classList.toggle('active',history);$('#editorTab').classList.toggle('active',!history);if(history)historyList()}\n$('#historyTab').onclick=async()=>{try{await loadRecords();tab(true)}catch(e){toast(e.message)}};$('#editorTab').onclick=()=>tab(false);$('#new').onclick=()=>{if(dirty&&!confirm('Start a new invoice? The current draft will be replaced. Save it first if you want to keep it.'))return;model=defaults();model.customer='';model.items=[{name:'',detail:'',qty:1,price:0}];dirty=false;bindForm();tab(false)};\nfunction historyList(){const q=$('#search').value.toLowerCase();const rows=records.filter(r=>(r.customer+' '+r.number).toLowerCase().includes(q));$('#records').innerHTML=rows.length?rows.map(r=>`<div class=\"record\"><div><strong>${esc(r.customer)}</strong><small>${esc(r.number)} · ${esc(r.date)} · LKR ${money(totals(r).total)}</small></div><div><button data-open=\"${esc(r.id)}\">Open</button><button data-delete=\"${esc(r.id)}\">Delete</button></div></div>`).join(''):'<div class=\"empty\">No saved invoices yet. Save your first invoice in the editor.</div>'}\n$('#search').oninput=historyList;$('#records').onclick=async e=>{if(e.target.dataset.open){if(dirty&&!confirm('Open saved invoice and replace the current draft?'))return;model=JSON.parse(JSON.stringify(records.find(r=>r.id===e.target.dataset.open)));dirty=false;bindForm();tab(false)}if(e.target.dataset.delete&&confirm('Delete this saved invoice? Export a backup first if you want to keep it.')){const id=e.target.dataset.delete;try{await api('/api/invoices/'+encodeURIComponent(id),{method:'DELETE',headers:{'If-Match':String(versions.get(id))}});records=records.filter(r=>r.id!==id);versions.delete(id);historyList();$('#count').textContent=records.length}catch(error){toast(error.message)}}};\n$('#backup').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:1,invoices:records,draft:model},null,2)],{type:'application/json'}));a.download='JANANEE-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};\nasync function importRecords(incoming){let added=0;for(const invoice of incoming){if(records.some(r=>r.id===invoice.id))continue;await uploadInvoice(invoice);records.push(invoice);added++}render();return added}\n$('#restore').onclick=()=>$('#backupFile').click();$('#backupFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10000000)throw Error('Backup is too large.');const backup=JSON.parse(await file.text());if(backup.version!==1||!Array.isArray(backup.invoices)||backup.invoices.length>2000)throw Error('Choose a valid JANANEE backup.');$('#restore').disabled=true;const added=await importRecords(backup.invoices);toast(added+' invoices restored to your account. Existing records kept.')}catch(error){toast(error.message)}finally{$('#restore').disabled=false;e.target.value=''}};\n$('#legacyImport').onclick=async()=>{try{const old=JSON.parse(localStorage.getItem(KEY)||'[]');if(!Array.isArray(old)||!old.length)return toast('No earlier browser invoices were found.');if(!confirm('Move '+old.length+' earlier browser invoices into this account? After a successful copy, those saved browser records will be removed.'))return;$('#legacyImport').disabled=true;await loadRecords();for(const invoice of old){const existing=records.find(r=>r.id===invoice.id);if(existing&&JSON.stringify(existing)!==JSON.stringify(invoice))throw Error('An earlier invoice has changed. Export a browser backup before importing.')}const count=await importRecords(old);localStorage.removeItem(KEY);toast(count+' invoices moved to your account.')}catch(error){toast(error.message)}finally{$('#legacyImport').disabled=false}};\n$('#account').onclick=()=>$('#accountDialog').showModal();$('#closeAccount').onclick=()=>$('#accountDialog').close();$('#passwordForm').onsubmit=async e=>{e.preventDefault();const current=$('#currentPassword'),next=$('#newPassword'),again=$('#repeatPassword'),message=$('#passwordMessage');message.textContent='';if(next.value!==again.value){message.textContent='New passwords do not match.';return}$('#updatePassword').disabled=true;try{await api('/api/auth/password',{method:'POST',body:JSON.stringify({currentPassword:current.value,password:next.value})});current.value=next.value=again.value='';message.textContent='Password changed. Other sessions have been signed out.'}catch(error){message.textContent=error.message}finally{$('#updatePassword').disabled=false}};\n$('#logout').onclick=async()=>{if(dirty&&!confirm('Sign out? Unsaved changes will be lost. Save your invoice or export a backup first.'))return;try{await api('/api/auth/logout',{method:'POST',body:'{}'});dirty=false;records=[];model=null;$('#preview').innerHTML='';location.replace('/admin/login')}catch(error){toast(error.message)}};\nwindow.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue=''}});\nwindow.addEventListener('pageshow',event=>{if(event.persisted)location.reload()});\nasync function boot(){try{await loadRecords();model=defaults();dirty=false;bindForm();$('#loading').hidden=true}catch(error){$('#loadingMessage').textContent=error.message;$('#retry').hidden=false}}\n$('#signinAgain').onclick=()=>{if(dirty&&!confirm('Sign in again? Unsaved changes will be lost. Export a backup first if needed.'))return;dirty=false;location.replace('/admin/login')};$('#retry').onclick=()=>location.reload();boot();\n"},"/auth.css":{"type":"text/css; charset=utf-8","base64":false,"content":"*{box-sizing:border-box}body{margin:0;font:14px Arial,sans-serif;color:#172c46;background:#f8f8f7}.auth-shell{display:grid;grid-template-columns:1fr 1fr;min-height:100vh}.story{background:#142b44;color:#fff;position:relative;padding:50px 60px;overflow:hidden;display:flex;flex-direction:column}.story:after{content:'';position:absolute;width:550px;height:550px;border:1px solid #ffffff0b;border-radius:50%;bottom:-300px;right:-160px;box-shadow:0 0 0 75px #ffffff02,0 0 0 150px #ffffff02}.wordmark{font:31px Georgia;letter-spacing:3px}.wordmark span{display:block;font:9px Arial;letter-spacing:3px;color:#d5b573;margin:11px 0 0 42px}.story-copy{margin:auto 0;padding:70px 0}.eyebrow{font-size:9px;letter-spacing:2px;color:#d5b573;line-height:1.8}h1{font:clamp(35px,4vw,60px)/1.2 Georgia;margin:25px 0}.story p{font-size:13px;line-height:1.9;color:#bac6d2}.cake{font:75px Georgia;color:#ddbd7c;margin-top:25px}.story footer{font-size:8px;letter-spacing:2px;color:#8095aa}.form-side{display:flex;align-items:center;justify-content:center;padding:50px 30px}.auth-card{width:100%;max-width:370px}.step{font-size:9px;letter-spacing:2px;color:#ac8c4c;margin-bottom:17px}h2{font:34px Georgia;margin:0 0 13px}.auth-card>p{color:#8b95a2;font-size:12px;line-height:1.8;margin-bottom:30px}label{display:block;font-size:11px;color:#657386;margin:0 0 20px}input{display:block;margin-top:9px;width:100%;padding:14px;border:1px solid #dbe1e7;border-radius:7px;background:white;font:14px Arial;color:#172c46}input:focus{outline:2px solid #d5b573;outline-offset:2px}.password-wrap{position:relative}.password-wrap input{padding-right:65px}.password-wrap button{position:absolute;right:8px;top:7px;padding:10px;font-size:10px;color:#8a7959;background:transparent;border:0;cursor:pointer}button{font:inherit;cursor:pointer}.submit{width:100%;padding:15px;background:#172e49;color:#fff;border:0;border-radius:7px;margin:5px 0 12px;font-size:12px}.submit:disabled{opacity:.45;cursor:default}.text-button{display:block;width:100%;border:0;background:transparent;font-size:11px;color:#9b814d;padding:12px}.privacy{border-top:1px solid #e5e6e8;margin-top:32px;padding-top:22px;color:#9ca4ad;font-size:10px;line-height:1.9}.mobile-brand{display:none}#error{padding:12px 14px;background:#fceeee;color:#a54242;border:1px solid #f0d3d3;border-radius:6px;margin-bottom:20px;font-size:12px;line-height:1.6}#passwordHint{font-size:11px;line-height:1.6;color:#8893a2;margin-top:-8px;margin-bottom:20px}.recovery-icon{width:40px;height:40px;border-radius:50%;background:#e7f1eb;color:#57836a;display:grid;place-items:center}#recovery h3{font:24px Georgia}#recovery p{font-size:12px;line-height:1.8;color:#8792a0}code{display:block;overflow-wrap:anywhere;background:#fff6e4;border:1px solid #ebddb8;border-radius:7px;padding:18px;font-size:15px;line-height:1.6;color:#6d5525;user-select:all}.recovery-actions{display:flex;gap:8px;margin:12px 0 20px}.recovery-actions button{background:#fff;border:1px solid #dee3e9;border-radius:5px;padding:10px;font-size:11px}.ack{display:flex;align-items:center;gap:8px}.ack input{width:auto;margin:0}.ack{line-height:1.6}[hidden]{display:none!important}@media(max-width:760px){.auth-shell{display:block}.story{display:none}.form-side{min-height:100vh;padding:35px 25px}.mobile-brand{display:block;text-decoration:none;color:#172e49;font:27px Georgia;letter-spacing:3px;margin-bottom:55px}}\n\n.owner-setup{display:block;text-align:center;text-decoration:none}.privacy a{color:#a3844c}\n"},"/auth.js":{"type":"text/javascript; charset=utf-8","base64":false,"content":"const $=s=>document.querySelector(s);let mode='login',recovery='';\nfunction error(message){$('#error').textContent=message;$('#error').hidden=!message}\nfunction view(next){mode=next;$('#email').type=mode==='login'?'text':'email';$('#email').closest('label').firstChild.textContent=mode==='login'?'Username or email':'Email address';error('');$('#authForm').hidden=false;$('#recovery').hidden=true;const fresh=mode==='register',reset=mode==='reset';$('#title').textContent=fresh?'Make yourself at home.':reset?'A fresh start.':'Welcome back.';$('#intro').textContent=fresh?'Set up your private invoice studio account.':reset?'Use your recovery code to choose a new password.':'Sign in to manage your invoices.';$('#recoveryLabel').hidden=!reset;$('#recoveryCode').required=reset;$('#confirmLabel').hidden=!(fresh||reset);$('#confirmPassword').required=fresh||reset;$('#password').minLength=fresh||reset?12:1;$('#password').autocomplete=fresh||reset?'new-password':'current-password';$('#password').value='';$('#confirmPassword').value='';$('#passwordHint').hidden=!(fresh||reset);$('#submit').textContent=fresh?'Create account →':reset?'Reset password':'Sign in →';$('#reset').hidden=mode!=='login';$('#back').hidden=!reset;$('#passwordLabel').firstChild.textContent=reset?'New password':'Password'}\nasync function request(path,data){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const b=await r.json();if(!r.ok)throw Error(b.error||'Please try again.');return b}\n$('#toggle').onclick=()=>{const p=$('#password');p.type=p.type==='password'?'text':'password';$('#toggle').textContent=p.type==='password'?'Show':'Hide'};\n$('#reset').onclick=()=>view('reset');$('#back').onclick=()=>view('login');\n$('#authForm').onsubmit=async e=>{e.preventDefault();error('');if(mode!=='login'&&$('#password').value!==$('#confirmPassword').value)return error('The passwords do not match.');$('#submit').disabled=true;try{const b=await request('/api/auth/'+mode,{email:$('#email').value,password:$('#password').value,recoveryCode:$('#recoveryCode').value});$('#password').value='';$('#confirmPassword').value='';if(b.recoveryCode){recovery=b.recoveryCode;$('#code').textContent=recovery;$('#authForm').hidden=true;$('#reset').hidden=true;$('#back').hidden=true;$('#recovery').hidden=false;$('#title').textContent='You’re all set.';$('#intro').textContent='One last step before you start.'}else location.replace('/admin')}catch(e){error(e.message)}finally{$('#submit').disabled=false}};\n$('#ack').onchange=()=>$('#continue').disabled=!$('#ack').checked;$('#continue').onclick=()=>location.replace('/admin');$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(recovery);$('#copy').textContent='Copied ✓'}catch{error('Select and copy the code manually.')}};\n$('#download').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['JANANEE Invoice Studio\\nEmail: '+$('#email').value+'\\nRecovery code: '+recovery+'\\nKeep this private. Each code can be used once.\\n'],{type:'text/plain'}));a.download='JANANEE-recovery-code.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};\nfetch('/api/auth/status').then(async r=>{if(!r.ok)throw Error('Unable to check your account. Reload to try again.');return r.json()}).then(s=>{if(s.authenticated)return location.replace('/admin');$('#email').value=s.suggestedEmail||'';s.registered?view('login'):s.setupAllowed?view('register'):ownerSetup()}).catch(e=>error(e.message));\n\nfunction ownerSetup(){error('');$('#title').textContent='Your shop, your space.';$('#intro').textContent='Only the shop owner can set up the admin account. Verify your owner account to get started.';$('#authForm').hidden=true;$('#ownerSetup').hidden=false}\n"},"/chocolate-cake.jpg":{"type":"image/jpeg","base64":true,"content":""},"/collage.css":{"type":"text/css; charset=utf-8","base64":false,"content":"/* A photo-journal composition made from the actual, published cake gallery. */\n.hero-mosaic{padding:0;min-height:535px;margin:35px 55px 35px 0;isolation:isolate}.hero-collage{position:absolute;inset:35px 0 35px;z-index:2}.mosaic-orbit{position:absolute;inset:60px -25px 70px -15px;border-radius:50%;background:radial-gradient(ellipse,#fff9ecb3 0%,#fff9ec33 65%,transparent 66%);border:1px solid #c9ad801c;transform:rotate(-15deg)}.mosaic-orbit:before{content:'';position:absolute;inset:20px -13px;border:1px solid #c5a67d1c;border-radius:50%}.mosaic-heading{position:absolute;left:5%;top:3px;font-size:7px;letter-spacing:2.1px;color:#b29a7d;transform:rotate(-3deg)}.memory-card{position:absolute;display:block;border:0;background:#fffaf1;padding:9px 9px 0;box-shadow:0 14px 30px #70533620,0 2px 5px #7053360b;cursor:pointer;text-align:left;will-change:transform;transition:box-shadow .4s,filter .4s;transform-origin:center center}.memory-photo{display:block;overflow:hidden;background:#eadccc;height:calc(100% - 38px)}.memory-photo img{display:block;width:100%;height:100%;object-fit:cover;object-position:center 65%;transition:transform .8s}.memory-caption{display:flex;align-items:center;justify-content:space-between;gap:6px;height:38px;font:12px Georgia;letter-spacing:.1px;color:#9c7e59;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.memory-caption>span{font:13px Arial;margin-right:3px;flex-shrink:0}.memory-card:hover{box-shadow:0 22px 38px #70533630;filter:brightness(1.025);z-index:8}.memory-card:hover img{transform:scale(1.05)}.memory-card:focus-visible{outline:2px solid #ac8956;outline-offset:6px;z-index:9}.memory-1{left:1%;top:12%;width:59%;height:79%;z-index:4;--tilt:-10deg;--bob:-7px;animation:memoryFloat 8s ease-in-out infinite}.memory-2{right:-1%;top:1%;width:48%;height:60%;z-index:2;--tilt:10deg;--bob:6px;animation:memoryFloat 9s -3s ease-in-out infinite}.memory-3{right:-3%;bottom:0;width:46%;height:56%;z-index:5;--tilt:8deg;--bob:-6px;animation:memoryFloat 7s -2s ease-in-out infinite}.mosaic-stamp{position:absolute;left:-4%;bottom:10%;z-index:6;width:105px;height:105px;border-radius:50%;border:1px solid #d7c5a3;background:#faf2e3;display:flex;flex-direction:column;align-items:center;justify-content:center;box-shadow:0 5px 18px #7053360a;transform:rotate(-11deg);pointer-events:none}.mosaic-stamp>span{font:12px Georgia;color:#9f815b}.mosaic-stamp>b{font:30px/1.1 Georgia;color:#b19660;font-weight:400;margin:3px 0}.mosaic-stamp>i{font:11px Georgia;color:#b29a79}.mosaic-sparkle{position:absolute;z-index:7;color:#bda16c;pointer-events:none;animation:twinkle 5s ease-in-out infinite}.sparkle-one{top:3%;left:-4%;font-size:43px}.sparkle-two{right:-7%;bottom:24%;font-size:23px;animation-delay:2s}.mosaic-bottom{position:absolute;bottom:0;left:7%;right:0;font-size:6px;letter-spacing:1.9px;color:#b79f81;display:flex;align-items:center;justify-content:space-between;gap:10px}.mosaic-bottom>span{font:17px Georgia;color:#bda06a}.count-1 .memory-1{left:20%;width:65%;top:5%;height:88%;--tilt:-5deg}.count-2 .memory-1{top:8%;height:80%}.count-2 .memory-2{top:23%;height:66%;right:-2%}.mosaic-empty{position:absolute;inset:10% 5%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border:1px solid #d5bf9a80;border-radius:45% 45% 0 0;color:#a68d68}.mosaic-empty>span{font:65px Georgia}.mosaic-empty>p{font:24px/1.5 Georgia}.mosaic-empty .button{font-size:9px}@keyframes memoryFloat{0%,100%{transform:translateY(0) rotate(var(--tilt))}50%{transform:translateY(var(--bob)) rotate(calc(var(--tilt) + 1.5deg))}}@media(max-width:1100px){.hero-mosaic{margin:35px 40px 35px 0;min-height:490px}.memory-card{padding:7px 7px 0}.memory-caption{font-size:10px;height:32px}.memory-photo{height:calc(100% - 32px)}.mosaic-stamp{width:85px;height:85px;left:-2%;bottom:11%}.mosaic-stamp>span{font-size:10px}.mosaic-stamp>i{font-size:9px}.mosaic-stamp>b{font-size:25px}.mosaic-heading{font-size:6px;letter-spacing:1.5px}.mosaic-bottom{font-size:5px;letter-spacing:1.4px}.sparkle-one{font-size:32px}}@media(max-width:650px){.hero-mosaic{height:440px;min-height:440px;margin:0 40px 20px 40px;padding:0}.hero-collage{inset:25px 0 35px}.mosaic-heading{left:7%;top:2px;font-size:6px;letter-spacing:1.3px}.memory-1{top:13%;left:2%;width:59%;height:80%}.memory-2{top:3%;right:-1%;width:48%;height:60%}.memory-3{bottom:-1%;right:-1%;width:47%;height:55%}.memory-caption{font-size:10px;height:31px}.memory-photo{height:calc(100% - 31px)}.mosaic-stamp{width:78px;height:78px;left:-3%;bottom:12%}.mosaic-stamp>span{font-size:9px}.mosaic-stamp>i{font-size:8px}.mosaic-stamp>b{font-size:23px}.mosaic-orbit{inset:35px -10px 40px -10px}.mosaic-bottom{left:1%;font-size:5px;letter-spacing:1.2px}.sparkle-one{left:-5%;top:8%;font-size:28px}.sparkle-two{right:-6%;bottom:28%;font-size:17px}.count-1 .memory-1{left:17%;width:70%;height:89%}.mosaic-empty>p{font-size:23px}}@media(max-width:370px){.hero-mosaic{margin-left:32px;margin-right:32px;height:390px;min-height:390px}.memory-caption{font-size:8px}.mosaic-stamp{width:67px;height:67px;left:-5%}.mosaic-stamp>span{font-size:8px}.mosaic-stamp>i{font-size:7px}}@media(prefers-reduced-motion:reduce){.memory-card{animation:none;transform:rotate(var(--tilt))}.mosaic-sparkle{animation:none}}\n"},"/cost-math.js":{"type":"text/javascript; charset=utf-8","base64":false,"content":"export const units={g:{group:'weight',factor:1},kg:{group:'weight',factor:1000},ml:{group:'volume',factor:1},l:{group:'volume',factor:1000},pcs:{group:'count',factor:1}};\nexport function validIngredient(item){return item&&typeof item.name==='string'&&!!item.name.trim()&&item.name.length<=100&&typeof item.purchaseUnit==='string'&&Object.hasOwn(units,item.purchaseUnit)&&typeof item.purchaseQuantity==='number'&&Number.isFinite(item.purchaseQuantity)&&item.purchaseQuantity>0&&item.purchaseQuantity<=1e6&&typeof item.purchasePrice==='number'&&Number.isFinite(item.purchasePrice)&&item.purchasePrice>0&&item.purchasePrice<=1e9&&Math.abs(item.purchasePrice*100-Math.round(item.purchasePrice*100))<0.00001}\nexport function lineCostCents(ingredient,quantity,unit){\n  if(!validIngredient(ingredient)||typeof quantity!=='number'||!Number.isFinite(quantity)||quantity<=0||quantity>1e6||typeof unit!=='string'||!Object.hasOwn(units,unit)||units[unit].group!==units[ingredient.purchaseUnit].group)throw Error('Choose a valid ingredient, quantity and matching unit.');\n  const cents=Math.round(ingredient.purchasePrice*100*(quantity*units[unit].factor)/(ingredient.purchaseQuantity*units[ingredient.purchaseUnit].factor));\n  if(!Number.isSafeInteger(cents)||cents>1e14)throw Error('This quantity is too large.');\n  return cents;\n}\n"},"/costing-ui.js":{"type":"text/javascript; charset=utf-8","base64":false,"content":"import * as CostMath from './cost-math.js';\nlet ingredientRows=[],savedCakeRows=[],editingIngredient=null,ingredientDraftId=crypto.randomUUID(),cakeDraftId=crypto.randomUUID(),costDraft=[newCostLine()],costReady=false;\nfunction newCostLine(){return{key:crypto.randomUUID(),ingredientId:'',quantity:'',unit:'g'}}\nconst ingredientById=id=>ingredientRows.find(r=>r.item.id===id);\nfunction resetIngredient(){editingIngredient=null;ingredientDraftId=crypto.randomUUID();$('#ingredientName').value='';$('#ingredientQuantity').value=1;$('#ingredientUnit').value='kg';$('#ingredientPrice').value='';$('#saveIngredient').textContent='Save ingredient';$('#cancelIngredient').hidden=true}\nfunction renderIngredients(){\n  const query=$('#ingredientSearch').value.trim().toLowerCase(),shown=ingredientRows.filter(r=>r.item.name.toLowerCase().includes(query));\n  $('#ingredientList').innerHTML=shown.length?shown.map(({item:i})=>`<div class=\"ingredient-record\"><div><strong>${esc(i.name)}</strong><small>${i.purchaseQuantity} ${esc(i.purchaseUnit)} · LKR ${money(i.purchasePrice)}</small></div><div><button type=\"button\" data-edit-ingredient=\"${esc(i.id)}\">Edit</button><button type=\"button\" data-delete-ingredient=\"${esc(i.id)}\">Delete</button></div></div>`).join(''):'<div class=\"empty\">'+(query?'No matching ingredients.':'Add an ingredient price to get started.')+'</div>';\n}\nfunction validCostLine(line){try{CostMath.lineCostCents(ingredientById(line.ingredientId)?.item,Number(line.quantity),line.unit);return true}catch{return false}}\nfunction finishCostLine(index){const line=costDraft[index];if(!line||!validCostLine(line))return;line.collapsed=true;renderCostLines()}\nfunction renderCostLines(){\n  for(const line of costDraft){const ingredient=ingredientById(line.ingredientId)?.item;if(ingredient&&CostMath.units[line.unit]?.group!==CostMath.units[ingredient.purchaseUnit].group)line.unit=ingredient.purchaseUnit;}\n  $('#cakeCostLines').innerHTML=costDraft.map((line,index)=>{const ingredient=ingredientById(line.ingredientId)?.item,group=CostMath.units[ingredient?.purchaseUnit]?.group||'weight',available=Object.keys(CostMath.units).filter(u=>CostMath.units[u].group===group);if(line.collapsed&&validCostLine(line))return `<div class=\"cost-line cost-line-compact\"><strong class=\"cost-line-name\">${esc(ingredient.name)}</strong><strong id=\"costAmount-${line.key}\"></strong><div class=\"cost-compact-actions\"><button type=\"button\" data-edit-cost=\"${index}\">Edit</button><button type=\"button\" data-remove-cost=\"${index}\" ${costDraft.length===1?'disabled':''}>Remove</button></div></div>`;return `<div class=\"cost-line\" data-cost-row=\"${index}\"><label>Ingredient<select data-cost-index=\"${index}\" data-cost-prop=\"ingredientId\" required><option value=\"\">Choose ingredient</option>${ingredientRows.map(({item:i})=>`<option value=\"${esc(i.id)}\" ${line.ingredientId===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select></label><div class=\"cost-quantity\"><label>Used quantity<input type=\"number\" data-cost-index=\"${index}\" data-cost-prop=\"quantity\" min=\"0.000001\" max=\"1000000\" step=\"any\" value=\"${esc(line.quantity)}\" required placeholder=\"250\"></label><label>Unit<select data-cost-index=\"${index}\" data-cost-prop=\"unit\">${available.map(u=>`<option value=\"${u}\" ${line.unit===u?'selected':''}>${u==='pcs'?'pieces':u}</option>`).join('')}</select></label></div><div class=\"cost-line-bottom\"><small>${ingredient?'Pack: '+ingredient.purchaseQuantity+' '+esc(ingredient.purchaseUnit)+' = LKR '+money(ingredient.purchasePrice):'Select an ingredient from your price list.'}</small><strong id=\"costAmount-${line.key}\">—</strong><button type=\"button\" data-finish-cost=\"${index}\">Done</button><button type=\"button\" data-remove-cost=\"${index}\" ${costDraft.length===1?'disabled':''} aria-label=\"Remove ingredient ${index+1}\">Remove</button></div></div>`}).join('');updateCostTotal();\n}\nfunction updateCostTotal(){\n  let total=0,valid=true;\n  for(const line of costDraft){let cents=null;try{cents=CostMath.lineCostCents(ingredientById(line.ingredientId)?.item,Number(line.quantity),line.unit);total+=cents}catch{valid=false}const label=$('#costAmount-'+line.key);if(label)label.textContent=cents===null?'—':'LKR '+money(cents/100)}\n  $('#cakeCostTotal').textContent=valid?money(total/100):'—';return valid;\n}\n\nconst orderedCostInvoices=()=>[...records].sort((a,b)=>a.number.localeCompare(b.number,undefined,{numeric:true}));\nfunction renderInvoiceChoices(){const selected=$('#cakeCostInvoice').value;$('#cakeCostInvoice').innerHTML='<option value=\"\">Choose invoice number</option>'+orderedCostInvoices().map(invoice=>{const saved=savedCakeRows.some(r=>r.item.invoiceId===invoice.id);return '<option value=\"'+esc(invoice.id)+'\" '+(saved?'disabled':'')+'>'+esc(invoice.number)+' ? '+esc(invoice.customer)+(saved?' ? Cost saved':'')+'</option>'}).join('');$('#cakeCostInvoice').value=records.some(i=>i.id===selected)&&!savedCakeRows.some(r=>r.item.invoiceId===selected)?selected:''}\nfunction selectCostInvoice(id){const invoice=records.find(r=>r.id===id);if(!invoice||savedCakeRows.some(r=>r.item.invoiceId===id)){$('#cakeCostInvoice').value='';return}if(cakeDraftId!==id&&costDraft.some(l=>l.ingredientId)&&!confirm('Replace the current cake costing with a new invoice?')){$('#cakeCostInvoice').value=records.some(i=>i.id===cakeDraftId)?cakeDraftId:'';return}if(cakeDraftId!==id)costDraft=[newCostLine()];cakeDraftId=id;$('#cakeCostInvoice').value=id;$('#cakeCostName').value=(invoice.items?.[0]?.name||'').slice(0,100);$('#cakeCostHeading').textContent='Cost for '+invoice.number;renderCostLines()}\n$('#cakeCostInvoice').onchange=event=>selectCostInvoice(event.target.value);\nasync function loadCosting(){\n  costReady=false;$('#ingredientFields').disabled=true;$('#cakeCostFields').disabled=true;$('#costingMessage').textContent='Loading ingredient prices and saved cake costings…';\n  try{const [ingredients,cakes]=await Promise.all([api('/api/ingredients'),api('/api/cake-costings'),loadRecords()]);ingredientRows=ingredients.items;savedCakeRows=cakes.items;renderIngredients();renderCostLines();renderInvoiceChoices();if(!$('#cakeCostInvoice').value){const next=orderedCostInvoices().find(i=>!savedCakeRows.some(r=>r.item.invoiceId===i.id));if(next&&!costDraft.some(l=>l.ingredientId))selectCostInvoice(next.id)}costReady=true;$('#costingMessage').textContent=''}catch(error){$('#costingMessage').textContent=error.message}finally{$('#ingredientFields').disabled=!costReady;$('#cakeCostFields').disabled=!costReady}\n}\n$('#costingTab').onclick=async()=>{moneySection(true);$('#adminTitle').textContent='Every cake, carefully costed.';$('#adminSubtitle').textContent='Save ingredient prices. Enter what each cake uses.';await loadCosting()};\n$('#cancelIngredient').onclick=()=>{resetIngredient();$('#ingredientMessage').textContent=''};\n$('#ingredientForm').onsubmit=async event=>{\n  event.preventDefault();if(!costReady||$('#ingredientFields').disabled||!$('#ingredientForm').reportValidity())return;\n  const item={id:editingIngredient?.item.id||ingredientDraftId,name:$('#ingredientName').value.trim(),purchaseQuantity:Number($('#ingredientQuantity').value),purchaseUnit:$('#ingredientUnit').value,purchasePrice:Number($('#ingredientPrice').value)};\n  if(!CostMath.validIngredient(item)){$('#ingredientMessage').textContent='Enter a valid name, pack quantity and price.';return}\n  $('#ingredientFields').disabled=true;$('#cakeCostFields').disabled=true;$('#ingredientMessage').textContent='Saving ingredient…';\n  try{const result=await api('/api/ingredients/'+encodeURIComponent(item.id),{method:'PUT',body:JSON.stringify({item,revision:editingIngredient?.revision||0})});const index=ingredientRows.findIndex(r=>r.item.id===item.id),row={item:result.item,revision:result.revision};if(index<0)ingredientRows.unshift(row);else ingredientRows[index]=row;resetIngredient();renderIngredients();renderCostLines();$('#ingredientMessage').textContent='Ingredient price saved.'}catch(error){$('#ingredientMessage').textContent=error.message}finally{$('#ingredientFields').disabled=false;$('#cakeCostFields').disabled=false}\n};\n$('#ingredientList').onclick=async event=>{\n  if(!costReady||$('#ingredientFields').disabled||$('#cakeCostFields').disabled)return;\n  const button=event.target.closest('button');if(!button)return;const id=button.dataset.editIngredient||button.dataset.deleteIngredient,row=ingredientById(id);if(!row)return;\n  if(button.dataset.editIngredient){if($('#ingredientName').value&&!confirm('Replace the ingredient entry you are editing?'))return;moneySection(true);$('#adminTitle').textContent='Every cake, carefully costed.';$('#adminSubtitle').textContent='Edit your ingredient price.';editingIngredient=JSON.parse(JSON.stringify(row));const i=row.item;$('#ingredientName').value=i.name;$('#ingredientQuantity').value=i.purchaseQuantity;$('#ingredientUnit').value=i.purchaseUnit;$('#ingredientPrice').value=i.purchasePrice;$('#saveIngredient').textContent='Update ingredient';$('#cancelIngredient').hidden=false;return}\n  if(!confirm('Delete this ingredient price? Saved cake costings will keep their original prices.'))return;button.disabled=true;\n  try{await api('/api/ingredients/'+encodeURIComponent(id),{method:'DELETE',headers:{'If-Match':String(row.revision)}});ingredientRows=ingredientRows.filter(r=>r.item.id!==id);if(editingIngredient?.item.id===id)resetIngredient();renderIngredients();renderCostLines()}catch(error){$('#ingredientMessage').textContent=error.message}finally{button.disabled=false}\n};\n$('#cakeCostLines').oninput=event=>{const input=event.target,index=input.dataset.costIndex;if(index===undefined||input.dataset.costProp!=='quantity')return;costDraft[Number(index)].quantity=input.value;updateCostTotal()};\n$('#cakeCostLines').onchange=event=>{const input=event.target,index=input.dataset.costIndex;if(index===undefined)return;const line=costDraft[Number(index)];if(input.dataset.costProp==='ingredientId'){line.ingredientId=input.value;const ingredient=ingredientById(input.value)?.item;line.unit=ingredient?({weight:'g',volume:'ml',count:'pcs'}[CostMath.units[ingredient.purchaseUnit].group]):'g';renderCostLines()}else if(input.dataset.costProp==='unit'){line.unit=input.value;updateCostTotal()}};\n$('#cakeCostLines').onfocusout=event=>{const row=event.target.closest('[data-cost-row]');if(!row?.isConnected||row.contains(event.relatedTarget))return;const next=event.relatedTarget?.dataset,index=next?.costIndex,prop=next?.costProp;finishCostLine(Number(row.dataset.costRow));if(index!==undefined&&prop)$('[data-cost-index=\"'+index+'\"][data-cost-prop=\"'+prop+'\"]')?.focus?.()};\n$('#cakeCostLines').onclick=event=>{if(event.target.dataset.finishCost!==undefined){finishCostLine(Number(event.target.dataset.finishCost));return}if(event.target.dataset.editCost!==undefined){costDraft[Number(event.target.dataset.editCost)].collapsed=false;renderCostLines();return}const index=event.target.dataset.removeCost;if(index===undefined||costDraft.length===1)return;costDraft.splice(Number(index),1);renderCostLines()};\n$('#addCostLine').onclick=()=>{if(costDraft.length>=50)return toast('Maximum 50 ingredients per cake.');costDraft.forEach(line=>{if(validCostLine(line))line.collapsed=true});costDraft.push(newCostLine());renderCostLines()};\n$('#cakeCostForm').onsubmit=async event=>{\n  event.preventDefault();if(!costReady||$('#cakeCostFields').disabled||!$('#cakeCostForm').reportValidity()||!updateCostTotal())return;\n  const invoice=records.find(r=>r.id===$('#cakeCostInvoice').value);if(!invoice){$('#cakeCostMessage').textContent='Choose a saved invoice number first.';return}\n  const item={id:invoice.id,invoiceId:invoice.id,name:$('#cakeCostName').value.trim(),date:today(),lines:costDraft.map(line=>({ingredientId:line.ingredientId,quantity:Number(line.quantity),unit:line.unit,ingredientRevision:ingredientById(line.ingredientId)?.revision}))};\n  $('#cakeCostFields').disabled=true;$('#ingredientFields').disabled=true;$('#cakeCostMessage').textContent='Saving cake costing…';\n  try{const result=await api('/api/cake-costings/'+encodeURIComponent(item.id),{method:'PUT',body:JSON.stringify({item,revision:0})});savedCakeRows.unshift({item:result.item,revision:result.revision});cakeDraftId=crypto.randomUUID();costDraft=[newCostLine()];$('#cakeCostName').value='';$('#cakeCostInvoice').value='';$('#cakeCostHeading').textContent='Cost for a saved invoice';renderCostLines();renderInvoiceChoices();const next=orderedCostInvoices().find(i=>!savedCakeRows.some(r=>r.item.invoiceId===i.id));if(next)selectCostInvoice(next.id);$('#cakeCostMessage').textContent=result.item.name+' saved · LKR '+money(result.item.totalCents/100)+'. Ready for the next cake.'}catch(error){$('#cakeCostMessage').textContent=error.message}finally{$('#cakeCostFields').disabled=false;$('#ingredientFields').disabled=false}\n};\n\nfunction cakeProfit(invoice,costing){\n  if(!costing)return null;\n  const saleCents=Math.round(totals(invoice).total*100),costCents=costing.totalCents;\n  return{saleCents,costCents,profitCents:saleCents-costCents};\n}\n\nconst profitExpanded=new Set();\nfunction renderOneByOne(){\n  const selected=$('#profitInvoice').value,invoices=orderedCostInvoices().filter(i=>!selected||i.id===selected);$('#profitMessage').textContent=invoices.length?'':'No saved invoices yet. Save an invoice first.';\n  $('#profitCards').innerHTML=invoices.map(invoice=>{\n    const costing=savedCakeRows.find(r=>r.item.invoiceId===invoice.id)?.item,result=cakeProfit(invoice,costing),expanded=profitExpanded.has(invoice.id),saleCents=Math.round(totals(invoice).total*100),label=result?(result.profitCents<0?'LOSS':result.profitCents===0?'BREAK EVEN':'PROFIT'):'PROFIT / LOSS';\n    const name=costing?.name||invoice.items.map(i=>i.name).join(', ');\n    const details=result?'<div id=\"profitDetails-'+esc(invoice.id)+'\" class=\"profit-card-details\" '+(expanded?'':'hidden')+'><h3>Ingredient costs</h3><div class=\"saved-cost-lines\">'+costing.lines.map(line=>'<div><span>'+esc(line.name)+'<small>'+line.quantity+' '+esc(line.unit)+' ? Pack '+line.purchaseQuantity+' '+esc(line.purchaseUnit)+' = LKR '+money(line.purchasePrice)+'</small></span><strong>LKR '+money(line.costCents/100)+'</strong></div>').join('')+'</div><p class=\"settings-note\">LKR '+money(result.saleCents/100)+' selling price ? LKR '+money(result.costCents/100)+' saved cake cost = LKR '+money(Math.abs(result.profitCents)/100)+' '+label.toLowerCase()+'. Selling price includes invoice discounts.</p></div>':'';\n    return '<article class=\"cost-card profit-cake-card\" data-profit-invoice=\"'+esc(invoice.id)+'\"><div class=\"profit-card-heading\"><div><h2>'+esc(invoice.number)+'</h2><strong>'+esc(name)+'</strong><p>'+esc(invoice.customer)+'</p></div><span>'+esc(invoice.date||'')+'</span></div><div class=\"profit-card-stats\"><div><span>SELLING PRICE (LKR)</span><strong>'+money(saleCents/100)+'</strong></div><div><span>SAVED CAKE COST (LKR)</span><strong>'+(result?money(result.costCents/100):'Not added')+'</strong></div><div class=\"profit-result\" data-result=\"'+(result&&result.profitCents<0?'loss':'profit')+'\"><span>'+label+' (LKR)</span><strong>'+(result?money(Math.abs(result.profitCents)/100):'?')+'</strong></div></div>'+(result?'<button type=\"button\" class=\"secondary\" data-full-profit=\"'+esc(invoice.id)+'\" aria-expanded=\"'+expanded+'\" aria-controls=\"profitDetails-'+esc(invoice.id)+'\">'+(expanded?'Less details':'Full details')+'</button>':'<p class=\"settings-note\">Save this cake?s ingredient cost to calculate its profit.</p><button type=\"button\" class=\"secondary\" data-add-profit-cost=\"'+esc(invoice.id)+'\">Add cake costing</button>')+details+'</article>';\n  }).join('');\n}\nasync function loadOneByOne(){\n  const selected=$('#profitInvoice').value;$('#profitCards').innerHTML='';$('#profitInvoice').disabled=true;$('#refreshOneByOne').disabled=true;$('#profitMessage').textContent='Loading saved invoice prices and cake costs?';\n  try{const [,cakes]=await Promise.all([loadRecords(),api('/api/cake-costings')]);savedCakeRows=cakes.items;const invoices=orderedCostInvoices();$('#profitInvoice').innerHTML='<option value=\"\">All cakes</option>'+invoices.map(invoice=>'<option value=\"'+esc(invoice.id)+'\">'+esc(invoice.number)+' ? '+esc(invoice.customer)+'</option>').join('');$('#profitInvoice').value=records.some(i=>i.id===selected)?selected:'';renderOneByOne();$('#profitInvoice').disabled=!invoices.length}catch(error){$('#profitMessage').textContent=error.message}finally{$('#refreshOneByOne').disabled=false}\n}\n$('#oneByOneTab').onclick=async()=>{moneySection('one');$('#adminTitle').textContent='Your cakes, one by one.';$('#adminSubtitle').textContent='Compare each invoice price with its saved cake cost.';await loadOneByOne()};\n$('#profitInvoice').onchange=renderOneByOne;\n$('#refreshOneByOne').onclick=loadOneByOne;\n$('#profitCards').onclick=async event=>{const button=event.target.closest('button');if(!button)return;const id=button.dataset.fullProfit;if(id){if(profitExpanded.has(id))profitExpanded.delete(id);else profitExpanded.add(id);renderOneByOne();$('#profitCards').querySelector('[data-full-profit=\"'+id+'\"]')?.focus();return}if(button.dataset.addProfitCost){const invoiceId=button.dataset.addProfitCost;await $('#costingTab').onclick();if(costReady)selectCostInvoice(invoiceId)}};\n\n$('#ingredientsTab').onclick=async()=>{moneySection('ingredients');$('#adminTitle').textContent='Your ingredients.';$('#adminSubtitle').textContent='Saved ingredient quantities and purchase prices.';$('#ingredientsMessage').textContent='Loading saved ingredients?';$('#ingredientList').innerHTML='';await loadCosting();$('#ingredientsMessage').textContent=costReady?'':$('#costingMessage').textContent};\n$('#ingredientSearch').oninput=renderIngredients;\n$('#addIngredientFromList').onclick=()=>$('#costingTab').onclick();\n"},"/DejaVuSans-Bold.ttf":{"type":"font/ttf","base64":true,"content":""},"/DejaVuSans.ttf":{"type":"font/ttf","base64":true,"content":""},"/DejaVuSerif.ttf":{"type":"font/ttf","base64":true,"content":""},"/gallery.css":{"type":"text/css; charset=utf-8","base64":false,"content":"@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Playfair+Display:ital,wght@0,400;0,500;1,400&display=swap');\n:root{--ink:#203b47;--cream:#fffdf9;--sand:#f6eee5;--gold:#af8d57;--muted:#9c9185;--serif:'Playfair Display',Georgia,serif}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:100px}body{margin:0;background:var(--cream);color:var(--ink);font:13px 'DM Sans',Arial,sans-serif}button,input{font:inherit}a{color:inherit}button,a{touch-action:manipulation;-webkit-tap-highlight-color:transparent}button{cursor:pointer}a:focus-visible,button:focus-visible{outline:2px solid var(--gold);outline-offset:5px}a{text-decoration:none}[hidden]{display:none!important}.announcement{text-align:center;padding:11px;background:#203b47;color:#dfd2bb;font-size:9px;letter-spacing:1.5px}header{height:108px;padding:22px 6%;display:flex;align-items:center;justify-content:space-between;gap:25px;background:#fffdf9f5;z-index:30;position:sticky;top:0;transition:box-shadow .4s,height .4s;backdrop-filter:blur(15px)}header.scrolled{box-shadow:0 8px 30px #203b4708;height:82px}.brand{text-align:center;display:inline-block}.brand>span{font:28px Georgia;letter-spacing:4px}.brand small{display:block;margin-top:9px;font-size:8px;letter-spacing:3px;color:var(--gold);text-transform:uppercase}nav{display:flex;gap:35px}nav a{font-size:11px;color:#8d8d83;position:relative}nav a:after{content:'';position:absolute;bottom:-8px;left:0;width:0;height:1px;background:var(--gold);transition:width .3s}nav a:hover:after{width:100%}.header-call{border:1px solid #d9cfbd;padding:12px 18px;border-radius:3px;font-size:10px;transition:background .3s}.header-call span{margin-left:15px;color:var(--gold)}.header-call:hover{background:var(--sand)}.hero{margin:0 3%;display:grid;grid-template-columns:1fr 1.02fr;background:#f4eae1;min-height:610px;position:relative;overflow:hidden}.hero-copy{align-self:center;padding:65px 8% 65px 13%;z-index:2}.eyebrow{font-size:9px;letter-spacing:2.1px;color:var(--gold);line-height:1.9}h1{font:clamp(43px,4.3vw,69px)/1.12 var(--serif);font-weight:400;letter-spacing:-1.8px;margin:25px 0;max-width:530px}h2{font:43px/1.22 var(--serif);font-weight:400;letter-spacing:-1px;margin:17px 0}h2 i{color:#ad8a68;font-weight:400}.hero-copy>p{font-size:12px;line-height:2;color:#9d8b7c;max-width:335px;margin-bottom:30px}.hero-actions{display:flex;align-items:center;gap:25px;flex-wrap:wrap}.button{display:inline-flex;align-items:center;justify-content:center;gap:28px;font-size:10px;padding:16px 23px;border-radius:2px;border:1px solid #cfc4b3;background:transparent;transition:transform .3s,box-shadow .3s,background .3s}.button:hover{transform:translateY(-3px);box-shadow:0 8px 20px #203b4712}.button span{transition:transform .3s}.button:hover span{transform:translate(3px,-3px)}.dark{background:var(--ink);color:#fff;border-color:var(--ink)}.outline{color:#8b7458}.text-link{font-size:10px;color:#8d7961;border-bottom:1px solid #cbb69a;padding-bottom:5px}.hero-footnote{font-size:10px;color:#ac9580;margin-top:40px}.hero-footnote>span:first-child{font:22px Georgia;margin-right:7px;color:#aa8c57}.hero-visual{position:relative;padding:28px 50px 45px 0;align-self:stretch;min-height:500px}.hero-image-wrap{height:100%;width:100%;overflow:hidden;position:relative;border-radius:45% 45% 0 0}.hero-image-wrap img{height:100%;width:100%;object-fit:cover;object-position:center 60%;position:absolute;animation:heroZoom 1.6s ease both}.hero-image-wrap:after{content:'';position:absolute;inset:0;border:1px solid #fffffa55;border-radius:45% 45% 0 0;margin:12px;pointer-events:none}.image-shine{position:absolute;inset:0;background:linear-gradient(115deg,transparent 40%,#fff8 50%,transparent 60%);transform:translateX(-150%);animation:shine 1.5s .8s forwards;pointer-events:none}.floating-note{position:absolute;left:-65px;bottom:100px;z-index:3;background:#fff9eeef;backdrop-filter:blur(4px);height:140px;width:140px;border:1px solid #e5d5b9;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;font:18px/1.4 var(--serif);color:#947c59;transform:rotate(-9deg);box-shadow:0 5px 25px #6e4b2410;animation:floatNote 6s ease-in-out infinite}.floating-note i{font-size:20px}.floating-note>span{font-size:19px;color:#ba9a60;margin-top:3px}.hero-image-caption{position:absolute;bottom:20px;left:0;right:50px;display:flex;justify-content:space-between;font-size:7px;letter-spacing:2px;color:#b19a83}.hero-vertical{position:absolute;bottom:42px;right:14px;writing-mode:vertical-rl;font-size:7px;letter-spacing:2px;color:#bca88e}.sparkle{position:absolute;color:#c5a365;pointer-events:none;animation:twinkle 4s ease-in-out infinite}.sparkle.one{left:-25px;top:62px;font-size:38px}.sparkle.two{right:15px;top:40%;font-size:20px;animation-delay:2s}.marquee{overflow:hidden;padding:24px 0;border-bottom:1px solid #e9dfd3;background:#fffdf9}.marquee-track{width:max-content;display:flex;gap:55px;align-items:center;animation:marquee 45s linear infinite;font-size:10px;color:#a1907a;letter-spacing:1px}.marquee b{font-size:12px;color:#bc9f6b;font-weight:400}.collection{padding:95px 7% 70px;max-width:1500px;margin:auto}.section-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:35px}.section-heading>p{font-size:11px;line-height:1.9;color:#a19688;padding-bottom:7px}.collection-controls{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:35px 0 30px}#filters{display:flex;gap:9px;flex-wrap:wrap}#filters button{border:1px solid #e1d7c7;color:#a18e75;background:transparent;border-radius:25px;padding:10px 17px;font-size:9px;transition:background .3s,color .3s,transform .3s}#filters button:hover{transform:translateY(-2px)}#filters button.active{background:var(--ink);color:#fff;border-color:var(--ink)}.search input{border:0;border-bottom:1px solid #d6c9b5;background:transparent;padding:11px 4px;font-size:10px;width:200px;color:var(--ink);outline-color:#b9a17a}.cake-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:30px}.cake-card{min-width:0}.cake-photo{position:relative;aspect-ratio:4/5;border-radius:3px;overflow:hidden;background:var(--sand);cursor:pointer;width:100%;border:0;display:block;padding:0;text-align:left}.cake-photo img{height:100%;width:100%;object-fit:cover;transition:transform .7s cubic-bezier(.2,.65,.3,1),filter .7s}.cake-photo:hover img{transform:scale(1.06);filter:brightness(.92)}.cake-photo:after{content:'';position:absolute;inset:0;box-shadow:inset 0 0 0 0 #ffffff50;transition:box-shadow .5s;pointer-events:none}.cake-photo:hover:after{box-shadow:inset 0 0 0 12px #ffffff35}.photo-label{position:absolute;left:17px;top:17px;background:#fffaf0eb;padding:8px 12px;border-radius:20px;color:#9d8260;font-size:7px;letter-spacing:1px}.view-photo{position:absolute;right:18px;bottom:18px;width:35px;height:35px;border-radius:50%;background:#fffaf0e6;display:grid;place-items:center;font-size:19px;color:#9c825b;transition:transform .3s}.cake-photo:hover .view-photo{transform:rotate(45deg)}.cake-info{padding:20px 0}.cake-info .eyebrow{font-size:7px;letter-spacing:1.5px}.cake-info h3{font:23px/1.25 var(--serif);font-weight:400;margin:9px 0;overflow-wrap:anywhere}.cake-info p{font-size:11px;line-height:1.8;color:#a09383;margin:0 0 18px;overflow-wrap:anywhere}.cake-info>a{font-size:10px;border-bottom:1px solid #d0baa0;color:#9c805b;padding-bottom:6px}.cake-info>a span{margin-left:10px}.gallery-bottom{display:flex;justify-content:space-between;gap:25px;align-items:center;padding:30px 0 0;border-top:1px solid #e9e0d4;margin-top:25px;color:#ab9a85;font-size:10px}.gallery-bottom a{color:#9b7b50}.gallery-bottom a span{margin-left:20px}.story{display:grid;grid-template-columns:1fr 1fr;gap:9%;padding:85px 10%;background:#f5eee5;align-items:center}.story-image{position:relative;aspect-ratio:4/5}.story-image:before{content:'';position:absolute;inset:-15px 18px 18px -15px;border:1px solid #d7c3a4;z-index:0}.story-image img{position:relative;width:100%;height:100%;object-fit:cover;z-index:1}.story-image-tag{position:absolute;z-index:2;bottom:22px;left:20px;color:white;background:#2a3f4480;padding:10px 14px;font-size:7px;letter-spacing:2px;backdrop-filter:blur(5px)}.story-copy h2{font-size:43px}.story-copy p{font-size:11px;line-height:2.1;color:#a1927d;max-width:350px}.story-copy .button{margin-top:20px}.contact{background:#243d45;padding:90px 25px 70px;text-align:center;position:relative;overflow:hidden;color:#f8f1e4}.contact .eyebrow{color:#b8a37e}.contact h2{font-size:62px;font-weight:400;margin:24px 0}.contact h2 i{color:#d0b88e}.contact>p{font-size:12px;color:#a7b0aa;line-height:1.9}.contact-number{display:block;font:39px/1.5 var(--serif);font-weight:400;margin:18px auto 25px;position:relative;width:max-content;letter-spacing:2px}.contact-number:after{content:'';position:absolute;bottom:1px;left:0;width:100%;height:1px;background:#9b977c;transform:scaleX(.6);transition:transform .3s}.contact-number:hover:after{transform:scaleX(1)}.light{background:#efe2cb;color:#354a49;border-color:#efe2cb}.contact-details{display:flex;justify-content:center;gap:17px;margin-top:42px;font-size:10px;color:#a9b1a8;flex-wrap:wrap}.contact-orbit{position:absolute;right:-90px;top:50px;width:310px;height:310px;border-radius:50%;border:1px solid #ffffff0b;box-shadow:0 0 0 45px #ffffff03,0 0 0 90px #ffffff02;font:120px/310px Georgia;color:#ffffff04;animation:floatNote 10s ease-in-out infinite}footer{display:flex;justify-content:space-between;align-items:center;padding:40px 6%;gap:25px}footer>.brand span{font-size:23px}footer>.brand small{font-size:6px}footer>span{font-size:9px;color:#ab9b85}footer>div{display:flex;gap:25px;font-size:9px;color:#aa977a}.floating-contact{position:fixed;bottom:25px;right:25px;z-index:25;background:#fffaf0;color:#31484c;padding:14px 20px;box-shadow:0 5px 30px #213a4820;border:1px solid #decbaa;border-radius:35px;font-size:10px;display:flex;align-items:center;gap:9px;transition:transform .3s}.floating-contact:hover{transform:translateY(-4px)}.floating-contact>span:first-child{font-size:16px;color:#a78954;animation:phoneWiggle 6s ease infinite}.back-to-top{position:fixed;left:22px;bottom:24px;background:#fffaf0d9;z-index:20;width:37px;height:37px;border:1px solid #d9caae;border-radius:50%;color:#b19970;font-size:17px;backdrop-filter:blur(5px)}.cake-dialog{border:0;border-radius:5px;background:#fffdf9;padding:0;max-width:calc(100vw - 28px);width:850px;max-height:92dvh;overflow:auto;position:fixed;color:var(--ink);box-shadow:0 20px 100px #172f4455;animation:dialogIn .35s ease}.cake-dialog[open]{display:grid;grid-template-columns:1.1fr 1fr}.cake-dialog::backdrop{background:#152d3e90;backdrop-filter:blur(8px)}.dialog-photo{min-height:470px}.dialog-photo img{width:100%;height:100%;object-fit:cover;display:block}.dialog-copy{padding:60px 35px 40px;align-self:center}.dialog-copy h2{font-size:34px;overflow-wrap:anywhere}.dialog-copy>p{font-size:12px;line-height:1.9;color:#a18c78;white-space:pre-wrap}.enquiry-note{display:block;font-size:10px;line-height:1.9;color:#ad9c87;margin:25px 0}.dialog-copy .button{width:100%}.dialog-number{display:block;font-size:12px;text-align:center;letter-spacing:1px;margin-top:17px;color:#a2875c}.close-cake{position:absolute;right:15px;top:13px;z-index:2;background:#fffdf9e6;width:32px;height:32px;border:1px solid #e6d9c5;border-radius:50%;color:#a28969;font-size:21px}.empty{grid-column:1/-1;background:#f7f1e8;border:1px dashed #dcc9a9;padding:55px 20px;text-align:center;color:#a28f72;font-size:12px;line-height:1.9}.error{margin:20px 0;padding:15px;border:1px solid #eed2c6;background:#fff1e9;color:#a36551;font-size:12px}.loading-card{aspect-ratio:4/5;background:linear-gradient(100deg,#f4ece2 30%,#fbf7ef 50%,#f4ece2 70%);background-size:200% 100%;animation:skeleton 1.7s infinite}.preloader{position:fixed;inset:0;background:#fcf6ed;z-index:1000;display:flex;align-items:center;justify-content:center;flex-direction:column;transition:opacity .65s,visibility .65s;pointer-events:auto}.preloader.finished{opacity:0;visibility:hidden;pointer-events:none}.loader-orbit{position:relative;width:112px;height:112px;display:grid;place-items:center}.loader-orbit b{font:57px Georgia;font-weight:400;color:#28404a}.loader-orbit i{position:absolute;inset:0;border:1px solid #e4d4b9;border-top-color:#b49459;border-radius:50%;animation:spin 1.8s linear infinite}.loader-orbit>span{position:absolute;font:24px Georgia;color:#b79b66;top:-12px;left:43px;background:#fcf6ed;padding:0 5px;z-index:1;animation:heartBeat 1.7s ease-in-out infinite}.loader-name{font:20px Georgia;letter-spacing:6px;margin:28px 0 5px;color:#344b53}.preloader>p{font-size:10px;letter-spacing:1px;color:#af9879}.loader-line{height:1px;width:120px;background:#e6d9c3;margin-top:15px;overflow:hidden}.loader-line>span{display:block;height:1px;width:40%;background:#af8d57;animation:loaderLine 1.4s ease-in-out infinite}.intro{animation:fadeUp .9s both}.hero-copy .intro:nth-child(2){animation-delay:.12s}.hero-copy .intro:nth-child(3){animation-delay:.23s}.hero-copy .intro:nth-child(4){animation-delay:.35s}.hero-copy .intro:nth-child(5){animation-delay:.45s}.reveal.pending{opacity:0;transform:translateY(27px)}.reveal{transition:opacity .8s ease,transform .8s cubic-bezier(.2,.6,.3,1)}.reveal.visible{opacity:1;transform:translateY(0)}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}@keyframes fadeUp{from{opacity:0;transform:translateY(25px)}to{opacity:1;transform:translateY(0)}}@keyframes heroZoom{from{transform:scale(1.08);opacity:.4}to{transform:scale(1);opacity:1}}@keyframes shine{to{transform:translateX(150%)}}@keyframes floatNote{0%,100%{transform:translateY(0) rotate(-7deg)}50%{transform:translateY(-12px) rotate(-4deg)}}@keyframes twinkle{0%,100%{opacity:.4;transform:scale(.85) rotate(0)}50%{opacity:1;transform:scale(1.15) rotate(20deg)}}@keyframes marquee{to{transform:translateX(-50%)}}@keyframes spin{to{transform:rotate(360deg)}}@keyframes heartBeat{0%,100%{transform:scale(1)}50%{transform:scale(1.15)}}@keyframes loaderLine{0%{transform:translateX(-110%)}100%{transform:translateX(360%)}}@keyframes skeleton{to{background-position:-200% 0}}@keyframes phoneWiggle{0%,80%,100%{transform:rotate(0)}85%{transform:rotate(12deg)}90%{transform:rotate(-12deg)}95%{transform:rotate(6deg)}}@keyframes dialogIn{from{opacity:0;transform:translateY(12px) scale(.98)}to{opacity:1;transform:none}}@media(min-width:1500px){.hero,header,footer,.story{max-width:1500px;margin-left:auto;margin-right:auto}.hero{min-height:700px}}@media(max-width:950px){header{padding:20px 5%;height:95px}nav{gap:22px}nav a{font-size:10px}.hero{min-height:550px}.hero-copy{padding:55px 7% 55px 10%}h1{font-size:48px}.hero-visual{padding-right:35px}.floating-note{width:112px;height:112px;left:-50px;font-size:15px}.floating-note i{font-size:17px}.hero-actions{gap:19px}.hero-vertical{right:10px}.hero-image-caption{right:35px}.cake-grid{gap:20px}.cake-info h3{font-size:21px}.story{padding:65px 8%;gap:10%}.story-copy h2{font-size:36px}.section-heading h2{font-size:37px}.section-heading>p{font-size:10px}.contact h2{font-size:53px}}@media(max-width:650px){header{height:85px;padding:20px 6%}.brand>span{font-size:23px}.brand small{font-size:6px;letter-spacing:2.7px}nav{display:none}.header-call{font-size:9px;padding:10px 12px}.header-call span{margin-left:8px}.announcement{font-size:7px;padding:10px;letter-spacing:.7px}.hero{grid-template-columns:1fr;margin:0 4%;min-height:0}.hero-copy{padding:42px 9% 30px}.eyebrow{font-size:8px}h1{font-size:50px;letter-spacing:-1.5px;margin:21px 0}.hero-copy>p{font-size:11px}.hero-actions{gap:24px}.hero-footnote{margin-top:25px}.hero-visual{height:440px;min-height:0;padding:0 30px 35px 45px}.hero-image-wrap{border-radius:43% 43% 0 0}.floating-note{width:102px;height:102px;left:8px;bottom:80px;font-size:13px}.floating-note i{font-size:15px}.floating-note>span{font-size:15px}.hero-image-caption{left:45px;right:30px;bottom:16px;font-size:6px}.hero-vertical{font-size:5px;right:10px}.sparkle.one{left:18px;top:25px;font-size:25px}.sparkle.two{right:10px;font-size:16px}.marquee{padding:19px 0}.marquee-track{gap:30px;font-size:8px}.collection{padding:60px 6% 45px}.section-heading{align-items:flex-start;flex-direction:column;gap:0}.section-heading h2{font-size:36px;margin-bottom:15px}.section-heading>p{font-size:10px;line-height:1.8;margin-top:0}.collection-controls{align-items:stretch;flex-direction:column;gap:17px;margin:22px 0 25px}.search input{width:100%;font-size:11px}#filters button{font-size:8px;padding:9px 12px}#filters{gap:6px}.cake-grid{grid-template-columns:1fr;gap:20px}.cake-photo{aspect-ratio:4/4.5}.cake-info{padding:18px 0 20px}.cake-info h3{font-size:25px}.cake-info p{font-size:11px}.cake-info .eyebrow{font-size:7px}.gallery-bottom{flex-direction:column;align-items:flex-start;gap:17px;font-size:9px}.story{grid-template-columns:1fr;padding:55px 10%;gap:40px}.story-image{aspect-ratio:4/4.2;margin-left:12px}.story-copy h2{font-size:38px}.story-copy p{font-size:11px}.story-copy .button{margin-top:17px}.contact{padding:65px 25px 55px}.contact h2{font-size:46px}.contact>p{font-size:11px}.contact-number{font-size:32px}.contact-details{font-size:9px;gap:10px}.contact-orbit{right:-180px}footer{padding:32px 7%;flex-wrap:wrap;gap:28px}footer>span{display:none}footer>div{font-size:8px;gap:18px}.floating-contact{right:15px;bottom:18px;padding:12px 16px;font-size:9px}.back-to-top{bottom:18px;left:15px;width:33px;height:33px}.cake-dialog[open]{display:block;width:450px}.dialog-photo{min-height:0;height:360px}.dialog-photo img{object-position:center 60%}.dialog-copy{padding:27px}.dialog-copy h2{font-size:29px}.dialog-copy>p{font-size:11px}.enquiry-note{margin:20px 0}.reveal{transition-duration:.6s}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation:none!important;transition:none!important}.reveal.pending{opacity:1;transform:none}.image-shine{display:none}}\nbody:not(.site-ready) .intro,body:not(.site-ready) .hero-image-wrap img,body:not(.site-ready) .image-shine{animation-play-state:paused}\r\n@media(min-width:651px) and (max-width:950px){.hero-actions .text-link{display:none}.floating-note{left:-35px}}\r\n.hero-actions .text-link{display:none}\r\n"},"/gallery.html":{"type":"text/html; charset=utf-8","base64":false,"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#f9f2eb\"><title>JANANEE · Cake Shop</title><meta name=\"description\" content=\"Explore JANANEE's cake creations. Call 0767759606 to discuss a cake for your celebration in Kadawatha.\"><link rel=\"stylesheet\" href=\"/gallery.css\"><link rel=\"stylesheet\" href=\"/collage.css\"><noscript><style>#preloader{display:none}</style></noscript></head><body>\n<div id=\"preloader\" class=\"preloader\" role=\"status\" aria-live=\"polite\"><div class=\"loader-orbit\"><span>♡</span><i></i><b>J</b></div><div class=\"loader-name\">JANANEE</div><p>Preparing something sweet…</p><div class=\"loader-line\"><span></span></div></div>\n<div class=\"announcement\">A little care in every detail. A little joy in every celebration.</div><header id=\"siteHeader\"><a class=\"brand\" href=\"/\" aria-label=\"JANANEE home\"><span data-setting=\"name\">JANANEE</span><small data-setting=\"tagline\">CAKE SHOP</small></a><nav aria-label=\"Main navigation\"><a href=\"#collection\">Our cakes</a><a href=\"#our-story\">Our little world</a><a href=\"#contact\">Contact</a></nav><a class=\"header-call\" data-call href=\"tel:+94767759606\">Let’s talk cake <span>↗</span></a></header>\n<main><section class=\"hero\"><div class=\"hero-copy\"><div class=\"eyebrow intro\">FOR LIFE’S LOVELIEST LITTLE MOMENTS</div><h1 id=\"headline\" class=\"intro\">A little sweetness.<br>A lot of love.</h1><p id=\"description\" class=\"intro\">Take a peek at our cake creations. Found a design you love? Call us and let’s talk about your next celebration.</p><div class=\"hero-actions intro\"><a class=\"button dark\" href=\"#collection\">Discover our cakes <span>↗</span></a><a class=\"text-link\" href=\"#contact\">Get in touch</a></div><div class=\"hero-footnote intro\"><span>♡</span> From <span data-setting=\"location\">Kadawatha</span>, with love.</div></div><div class=\"hero-visual hero-mosaic\"><div class=\"mosaic-orbit\" aria-hidden=\"true\"></div><div class=\"mosaic-heading\">A LITTLE COLLECTION OF HAPPY MOMENTS</div><div id=\"heroCollage\" class=\"hero-collage\" aria-label=\"Explore our cake creations\"><button class=\"memory-card memory-1\" data-hero-view=\"chocolate-celebration\"><span class=\"memory-photo\"><img id=\"heroImage\" fetchpriority=\"high\" src=\"/chocolate-cake.jpg\" alt=\"Chocolate Celebration Cake\"></span><span class=\"memory-caption\">Chocolate Celebration Cake <span>↗</span></span></button><button class=\"memory-card memory-2\" data-hero-view=\"pink-rose\"><span class=\"memory-photo\"><img src=\"/pink-rose-cake.jpg\" alt=\"Pink Rose Cake\"></span><span class=\"memory-caption\">Pink Rose Cake <span>↗</span></span></button><button class=\"memory-card memory-3\" data-hero-view=\"yellow-swirl\"><span class=\"memory-photo\"><img src=\"/yellow-swirl-cake.jpg\" alt=\"Yellow Swirl Cake\"></span><span class=\"memory-caption\">Yellow Swirl Cake <span>↗</span></span></button></div><div class=\"mosaic-stamp\" aria-hidden=\"true\"><span>A little joy.</span><b>♡</b><i>A sweet memory.</i></div><span class=\"mosaic-sparkle sparkle-one\" aria-hidden=\"true\">✧</span><span class=\"mosaic-sparkle sparkle-two\" aria-hidden=\"true\">✦</span><div class=\"mosaic-bottom\">THREE LITTLE REASONS TO SMILE <span>♡</span></div></div><span class=\"hero-vertical\" aria-hidden=\"true\">SOMETHING SWEET. SOMETHING SPECIAL.</span></section>\n<div class=\"marquee\" aria-hidden=\"true\"><div class=\"marquee-track\"><span>A reason to celebrate</span><b>✦</b><span>Sweet little details</span><b>✦</b><span>Made for your happy moments</span><b>✦</b><span>A reason to celebrate</span><b>✦</b><span>Sweet little details</span><b>✦</b><span>Made for your happy moments</span><b>✦</b></div></div>\n<section id=\"collection\" class=\"collection\"><div class=\"section-heading reveal\"><div><div class=\"eyebrow\">A PEEK INTO OUR CAKE GALLERY</div><h2>Sweet moments,<br><i>beautifully made.</i></h2></div><p>A little inspiration for your next celebration.<br>See something you love? We’d love to hear from you.</p></div><div class=\"collection-controls reveal\"><div id=\"filters\" role=\"group\" aria-label=\"Cake categories\"></div><label class=\"search\"><span class=\"sr-only\">Search our cakes</span><input id=\"cakeSearch\" type=\"search\" placeholder=\"Find a little inspiration…\"></label></div><div id=\"cakeGrid\" class=\"cake-grid\"><div class=\"loading-card\"></div><div class=\"loading-card\"></div><div class=\"loading-card\"></div></div><div id=\"galleryError\" class=\"error\" role=\"alert\" hidden></div><button id=\"retryGallery\" class=\"button\" hidden>Try again</button><div class=\"gallery-bottom reveal\"><span>Every celebration starts with a conversation.</span><a data-call href=\"tel:+94767759606\">Call us to discuss your cake <span>↗</span></a></div></section>\n<section id=\"our-story\" class=\"story\"><div class=\"story-image reveal\"><img src=\"/yellow-swirl-cake.jpg\" alt=\"Yellow piped swirl cake by JANANEE\" loading=\"lazy\"><span class=\"story-image-tag\">A LITTLE SLICE OF HAPPY</span></div><div class=\"story-copy reveal\"><div class=\"eyebrow\">WELCOME TO OUR LITTLE WORLD</div><h2>A cake is just<br>the beginning<br>of a <i>happy memory.</i></h2><p>A birthday wish. A family gathering. A little surprise for someone you love. We love being a part of the moments you want to celebrate.</p><p>Browse our designs, choose your inspiration, and get in touch. We’ll chat about your ideas, your date and the details that make your cake feel like you.</p><a class=\"button outline\" href=\"#contact\">Let’s dream up your cake <span>↗</span></a></div></section>\n<section id=\"contact\" class=\"contact\"><span class=\"contact-orbit\" aria-hidden=\"true\">♡</span><div class=\"eyebrow reveal\">YOUR NEXT SWEET MOMENT STARTS HERE</div><h2 class=\"reveal\">Let’s make<br><i>something lovely.</i></h2><p class=\"reveal\" id=\"contactText\">Let’s make your celebration a little sweeter.</p><a class=\"contact-number reveal\" data-call data-setting=\"phone\" href=\"tel:+94767759606\">0767759606</a><a class=\"button light reveal\" data-call href=\"tel:+94767759606\">Contact us <span>↗</span></a><div class=\"contact-details reveal\"><span data-setting=\"location\">Kadawatha</span><span>·</span><a id=\"contactEmail\" href=\"mailto:jcskumara05@gmail.com\" data-setting=\"email\">jcskumara05@gmail.com</a></div></section>\n</main><footer><a class=\"brand\" href=\"/\"><span data-setting=\"name\">JANANEE</span><small data-setting=\"tagline\">CAKE SHOP</small></a><span>Made with care. Just like your cakes.</span><div><a href=\"#collection\">Our cakes</a><a href=\"/admin\">Admin ↗</a></div></footer><a class=\"floating-contact\" data-call href=\"tel:+94767759606\" aria-label=\"Call JANANEE on 0767759606\"><span>☎</span><span>Contact us</span></a><button id=\"backToTop\" class=\"back-to-top\" aria-label=\"Back to top\" hidden>↑</button>\n<dialog id=\"cakeDialog\" class=\"cake-dialog\"><button id=\"closeCake\" class=\"close-cake\" aria-label=\"Close cake photo\">×</button><div class=\"dialog-photo\"><img id=\"detailImage\" alt=\"\"></div><div class=\"dialog-copy\"><div class=\"eyebrow\" id=\"detailCategory\"></div><h2 id=\"detailName\"></h2><p id=\"detailDescription\"></p><span class=\"enquiry-note\">Love this design? Call us to discuss your celebration, availability and price.</span><a class=\"button dark\" data-call href=\"tel:+94767759606\">Contact us <span>↗</span></a><a class=\"dialog-number\" data-call data-setting=\"phone\" href=\"tel:+94767759606\">0767759606</a></div></dialog><script src=\"/gallery.js\"></script></body></html>\n"},"/gallery.js":{"type":"text/javascript; charset=utf-8","base64":false,"content":"const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));let cakes=[],settings={},category='All';\nfunction finishLoading(){document.body.classList.add('site-ready');$('#preloader').classList.add('finished');$('#preloader').setAttribute('aria-hidden','true')}\nconst loaderWatchdog=setTimeout(finishLoading,4000);\nconst reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;\nconst observer='IntersectionObserver' in window&&!reduce?new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.remove('pending');e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08}):null;\nfunction reveal(){if(!observer)return;document.querySelectorAll('.reveal:not(.visible)').forEach((e,i)=>{e.classList.add('pending');e.style.transitionDelay=Math.min(i%3*.09,.18)+'s';observer.observe(e)})}\nfunction phoneLink(value){let phone=value.replace(/[^+\\d]/g,'');if(/^0\\d{9}$/.test(phone))phone='+94'+phone.slice(1);return'tel:'+phone}\nfunction applySettings(){document.title=settings.name+' · '+settings.tagline;document.querySelectorAll('[data-setting]').forEach(e=>e.textContent=settings[e.dataset.setting]);document.querySelectorAll('[data-call]').forEach(e=>e.href=phoneLink(settings.phone));$('#headline').textContent=settings.headline;$('#description').textContent=settings.description;$('#contactText').textContent=settings.contactText;$('#contactEmail').href='mailto:'+settings.email;$('.floating-contact').setAttribute('aria-label','Call '+settings.name+' on '+settings.phone)}\nfunction render(){const q=$('#cakeSearch').value.toLowerCase(),filtered=cakes.filter(p=>(category==='All'||p.category===category)&&(p.name+' '+p.description).toLowerCase().includes(q));$('#cakeGrid').innerHTML=filtered.length?filtered.map(p=>`<article class=\"cake-card reveal\"><button class=\"cake-photo\" data-view=\"${esc(p.id)}\" aria-label=\"View ${esc(p.name)}\"><img src=\"${esc(p.image)}\" alt=\"${esc(p.name)}\" loading=\"lazy\"><span class=\"photo-label\">${p.featured?'A LITTLE FAVOURITE':'THE JANANEE GALLERY'}</span><span class=\"view-photo\" aria-hidden=\"true\">↗</span></button><div class=\"cake-info\"><div class=\"eyebrow\">${esc(p.category)}</div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><a href=\"${esc(phoneLink(settings.phone))}\">Contact us <span>↗</span></a></div></article>`).join(''):'<div class=\"empty\">'+(cakes.length?'No cakes match your search. Try another little inspiration.':'New cake creations are on their way. Call us to discuss your celebration.')+'</div>';reveal()}\nfunction detail(id){const p=cakes.find(c=>c.id===id);if(!p)return;$('#detailImage').src=p.image;$('#detailImage').alt=p.name;$('#detailName').textContent=p.name;$('#detailCategory').textContent=p.category;$('#detailDescription').textContent=p.description;$('#cakeDialog').showModal()}\n$('#cakeGrid').onclick=e=>{const button=e.target.closest('[data-view]');if(button)detail(button.dataset.view)};$('#closeCake').onclick=()=>$('#cakeDialog').close();$('#cakeDialog').onclick=e=>{if(e.target===$('#cakeDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};\n$('#filters').onclick=e=>{if(e.target.dataset.filter){category=e.target.dataset.filter;$('#filters').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.filter===category));render()}};$('#cakeSearch').oninput=render;\nfunction scrollState(){const y=window.scrollY;$('#siteHeader').classList.toggle('scrolled',y>25);$('#backToTop').hidden=y<550}window.addEventListener('scroll',scrollState,{passive:true});$('#backToTop').onclick=()=>window.scrollTo({top:0,behavior:reduce?'auto':'smooth'});\nasync function load(){try{$('#galleryError').hidden=true;$('#retryGallery').hidden=true;const r=await fetch('/api/gallery');if(!r.ok)throw Error('We couldn’t load the gallery. Please try again, or call 0767759606.');const data=await r.json();settings=data.settings;cakes=data.cakes;applySettings();renderHeroCollage();$('#filters').innerHTML=['All',...new Set(cakes.map(p=>p.category))].map(c=>`<button data-filter=\"${esc(c)}\" class=\"${category===c?'active':''}\">${esc(c)}</button>`).join('');render();const image=$('#heroImage');if(image&&!image.complete)await Promise.race([new Promise(resolve=>{image.addEventListener('load',resolve,{once:true});image.addEventListener('error',resolve,{once:true})}),new Promise(resolve=>setTimeout(resolve,1800))])}catch(error){$('#cakeGrid').innerHTML='';$('#galleryError').textContent=error.message;$('#galleryError').hidden=false;$('#retryGallery').hidden=false}finally{clearTimeout(loaderWatchdog);finishLoading();reveal()}}\n$('#retryGallery').onclick=load;reveal();load();\n\nfunction renderHeroCollage(){const galleryOrder=[...cakes.filter(c=>c.featured),...cakes.filter(c=>!c.featured)];const chocolate=galleryOrder.find(c=>c.id==='chocolate-celebration');const ordered=(chocolate?[chocolate,...galleryOrder.filter(c=>c.id!==chocolate.id)]:galleryOrder).slice(0,3);$('#heroCollage').className='hero-collage count-'+ordered.length;$('#heroCollage').innerHTML=ordered.length?ordered.map((c,i)=>'<button class=\"memory-card memory-'+(i+1)+'\" data-hero-view=\"'+esc(c.id)+'\" aria-label=\"View '+esc(c.name)+'\"><span class=\"memory-photo\"><img '+(i===0?'id=\"heroImage\" fetchpriority=\"high\" ':'')+'src=\"'+esc(c.image)+'\" alt=\"'+esc(c.name)+'\"></span><span class=\"memory-caption\">'+esc(c.name)+' <span>↗</span></span></button>').join(''):'<div class=\"mosaic-empty\"><span>♡</span><p>Your next sweet memory<br>starts with a little hello.</p><a class=\"button dark\" href=\"#contact\">Let’s talk cake ↗</a></div>';$('.mosaic-bottom').firstChild.textContent=ordered.length>1?'A LITTLE GALLERY OF HAPPY MOMENTS ':'YOUR NEXT SWEET MOMENT STARTS HERE ';}\n$('#heroCollage').onclick=e=>{const card=e.target.closest('[data-hero-view]');if(card)detail(card.dataset.heroView)};\n"},"/index.html":{"type":"text/html; charset=utf-8","base64":false,"content":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>JANANEE · Invoice Studio</title><link rel=\"stylesheet\" href=\"/style.css\"><link rel=\"stylesheet\" href=\"/admin.css\"></head>\n<body><aside><a class=\"brand\" href=\"#\">J<span>JANANEE<small>CAKE SHOP · INVOICE STUDIO</small></span></a><div class=\"nav-label\">WORKSPACE</div><button class=\"nav active\" id=\"galleryTab\">◈ &nbsp; Cake gallery</button><button class=\"nav\" id=\"settingsTab\">⚙ &nbsp; Website settings</button><a class=\"nav\" href=\"/\" target=\"_blank\" rel=\"noopener\">↗ &nbsp; View website</a><button class=\"nav\" id=\"editorTab\">▧ &nbsp; Invoice editor</button><button class=\"nav\" id=\"financeTab\"><svg class=\"nav-icon\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><rect x=\"2.5\" y=\"5\" width=\"19\" height=\"14\" rx=\"2\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M6 9h.01M18 15h.01\"/></svg>Money summary</button><button class=\"nav\" id=\"customersTab\"><svg class=\"nav-icon\" width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"9\" cy=\"7.5\" r=\"3\"/><path d=\"M3 21v-2a6 6 0 0 1 12 0v2M16 4.8a3 3 0 0 1 0 5.4M18 14a5 5 0 0 1 3 4.6V21\"/></svg>Customers <span id=\"customerCount\">0</span></button><button class=\"nav\" id=\"historyTab\">◷ &nbsp; Saved invoices <span id=\"count\">0</span></button><div class=\"aside-bottom\"><span class=\"dot\"></span> Saved to your account<small>Invoices sync across devices after you save.</small><button id=\"legacyImport\">Import earlier browser invoices</button><button id=\"account\">Account settings</button><button id=\"logout\">Sign out</button><button id=\"backup\">Export backup</button><button id=\"restore\">Restore backup</button><input type=\"file\" id=\"backupFile\" accept=\"application/json\" hidden></div></aside>\n<main><header><div><div class=\"eyebrow\">A LITTLE CARE IN EVERY DETAIL</div><h1 id=\"adminTitle\">Your cake gallery.</h1><p id=\"adminSubtitle\">A beautiful little window into your work.</p></div><button id=\"new\" class=\"secondary\">＋ New invoice</button></header>\n<section id=\"galleryPanel\" class=\"management-panel\"><div class=\"admin-stats\"><div><span>CAKES ON THE WEBSITE</span><strong id=\"visibleCakes\">—</strong></div><div><span>SAVED INVOICES</span><strong id=\"invoiceStat\">—</strong></div><div><span>CUSTOMER CONTACT</span><strong id=\"contactStat\">0767759606</strong></div></div><div class=\"admin-section-head\"><div><h2>Your creations</h2><p>Add photos, update details or hide a cake from the public gallery.</p></div><button id=\"newCake\" class=\"primary\">＋ Add cake</button></div><p class=\"management-error\" id=\"galleryAdminError\" role=\"alert\" hidden></p><div id=\"adminCakes\" class=\"admin-cakes\"></div></section><section id=\"settingsPanel\" class=\"management-panel\" hidden><div class=\"settings-card\"><div class=\"section-title\"><span>01</span><h2>Website & contact details</h2></div><form id=\"shopSettingsForm\"><div class=\"grid\"><label>Shop name<input name=\"name\" required maxlength=\"100\"></label><label>Tagline<input name=\"tagline\" maxlength=\"100\"></label></div><label>Homepage heading<input name=\"headline\" required maxlength=\"100\"></label><label>Homepage introduction<textarea name=\"description\" rows=\"3\" maxlength=\"500\"></textarea></label><div class=\"grid\"><label>Contact phone<input name=\"phone\" type=\"tel\" required maxlength=\"30\" pattern=\"[+0-9 ()-]{7,30}\"></label><label>Email<input name=\"email\" type=\"email\" maxlength=\"100\"></label></div><label>Location<input name=\"location\" maxlength=\"100\"></label><label>Contact section message<input name=\"contactText\" maxlength=\"100\"></label><p class=\"settings-note\">This information appears on your public website. Visitors contact you directly to discuss cake designs and prices.</p><p id=\"settingsMessage\" class=\"settings-message\" role=\"status\"></p><button class=\"primary\" id=\"saveSettings\">Save website settings</button></form></div></section><div id=\"editor\" hidden><div class=\"toolbar\"><div><span class=\"dot\"></span> <span id=\"state\">Ready to edit</span></div><div><button id=\"signinAgain\" class=\"secondary\" hidden>Sign in again</button><button id=\"save\" class=\"secondary\">Save invoice</button><button id=\"print\" class=\"primary\">↓ Print / Save PDF</button></div></div><div class=\"workspace\"><section class=\"panel\"><div class=\"section-title\"><span>01</span><h2>Invoice details</h2></div><div class=\"grid\"><label>Invoice number<input data-field=\"number\" maxlength=\"35\" required></label><label>Invoice date<input data-field=\"date\" type=\"date\" required></label></div><label>Customer name<input data-field=\"customer\" maxlength=\"80\" placeholder=\"Customer's full name\" required></label><label>Customer phone <em>optional</em><input data-field=\"customerPhone\" type=\"tel\" maxlength=\"30\" pattern=\"[+0-9 ()-]{7,30}\" placeholder=\"077 123 4567\" autocomplete=\"tel\"></label><label>Customer details <em>optional</em><textarea data-field=\"customerDetails\" rows=\"2\" maxlength=\"160\" placeholder=\"Address or other details\"></textarea></label><div class=\"section-title\"><span>02</span><h2>Order items</h2></div><div id=\"items\"></div><button id=\"add\" class=\"add\">＋ Add another item</button><div class=\"section-title\"><span>03</span><h2>Payment & notes</h2></div><div class=\"grid\"><label>Discount (LKR)<input data-field=\"discount\" type=\"number\" min=\"0\" step=\"0.01\"></label><label>Amount received (LKR)<input data-field=\"advance\" type=\"number\" min=\"0\" step=\"0.01\"></label></div><label>Invoice note <em>optional</em><textarea data-field=\"note\" maxlength=\"180\" rows=\"2\" placeholder=\"Collection details or a personal message\"></textarea></label><details><summary>Shop details & thank-you message</summary><label>Shop name<input data-field=\"shop\" maxlength=\"24\"></label><label>Tagline<input data-field=\"tagline\" maxlength=\"35\"></label><label>Phone<input data-field=\"phone\" maxlength=\"40\"></label><label>Email<input data-field=\"email\" maxlength=\"65\"></label><label>Location<input data-field=\"location\" maxlength=\"65\"></label><label>Footer line 1<input data-field=\"footer1\" maxlength=\"65\"></label><label>Footer line 2<input data-field=\"footer2\" maxlength=\"65\"></label></details></section><section class=\"preview-area\"><div class=\"preview-heading\"><span>LIVE PREVIEW</span><span>A4 · Original design</span></div><div id=\"preview\"></div><p class=\"print-tip\">PDF එක ගන්න: Print → Save as PDF · Paper: A4 · Margins: None</p></section></div></div>\n<section id=\"financePanel\" class=\"management-panel\" hidden><div class=\"money-switch\" role=\"group\" aria-label=\"Money summary sections\"><button type=\"button\" class=\"secondary active\" id=\"moneyOverviewTab\" aria-pressed=\"true\">Money summary</button><button type=\"button\" class=\"secondary\" id=\"ingredientsTab\" aria-pressed=\"false\">Ingredients</button><button type=\"button\" class=\"secondary\" id=\"costingTab\" aria-pressed=\"false\">Cake costing</button><button type=\"button\" class=\"secondary\" id=\"oneByOneTab\" aria-pressed=\"false\">One by one</button></div><div id=\"moneyOverview\"><div class=\"admin-section-head\"><div><h2>Your money, at a glance</h2><p>All saved invoices ? LKR</p></div><button id=\"refreshFinance\" class=\"secondary\">Refresh</button></div><p id=\"financeMessage\" class=\"settings-note\" role=\"status\"></p><div id=\"financeContent\" hidden><div class=\"admin-stats finance-stats\"><div><span>MONEY RECEIVED (LKR)</span><strong id=\"moneyReceived\">0.00</strong></div><div><span>TOTAL INVOICED (LKR)</span><strong id=\"moneyInvoiced\">0.00</strong></div><div><span>STILL TO RECEIVE (LKR)</span><strong id=\"moneyOutstanding\">0.00</strong></div></div><h2 class=\"payments-heading\">Invoice payments</h2><div class=\"finance-table-wrap\"><table class=\"finance-table\"><thead><tr><th>Invoice / Customer</th><th>Total</th><th>Received</th><th>Balance</th><th>Payment</th></tr></thead><tbody id=\"financeRows\"></tbody></table></div></div></div><section id=\"oneByOnePanel\" hidden><div class=\"admin-section-head\"><div><h2>Your cakes, one by one</h2><p>Each cake?s selling price, saved cost and profit.</p></div><button type=\"button\" class=\"secondary\" id=\"refreshOneByOne\">Refresh</button></div><div class=\"cost-card one-by-one-picker\"><label>Show cakes<select id=\"profitInvoice\" aria-label=\"Filter cake invoices\"><option value=\"\">All cakes</option></select></label></div><p class=\"settings-note\" id=\"profitMessage\" role=\"status\"></p><div id=\"profitCards\"></div></section><section id=\"ingredientsPanel\" hidden><p id=\"ingredientsMessage\" class=\"settings-note\" role=\"status\"></p><div class=\"admin-section-head\"><div><h2>Your saved ingredients</h2><p>Purchase quantities, units and prices for cake costing.</p></div><button id=\"addIngredientFromList\" type=\"button\" class=\"primary\">+ Add ingredient</button></div><div class=\"cost-card\"><label class=\"ingredient-search\">Search ingredients<input id=\"ingredientSearch\" type=\"search\" placeholder=\"Search by ingredient name\"></label><div id=\"ingredientList\"></div></div></section><section id=\"costingPanel\" hidden><p id=\"costingMessage\" class=\"settings-note\" role=\"status\"></p><div class=\"cost-layout\"><section class=\"cost-card\"><h2>Ingredient prices</h2><p class=\"settings-note\">Save the pack size and its price once.</p><form id=\"ingredientForm\"><fieldset id=\"ingredientFields\"><label>Ingredient / item<input id=\"ingredientName\" maxlength=\"100\" required placeholder=\"e.g. Cake flour\"></label><div class=\"grid\"><label>Purchase quantity<input id=\"ingredientQuantity\" type=\"number\" min=\"0.000001\" max=\"1000000\" step=\"any\" value=\"1\" required></label><label>Unit<select id=\"ingredientUnit\"><option value=\"kg\">kg</option><option value=\"g\">g</option><option value=\"l\">litre</option><option value=\"ml\">ml</option><option value=\"pcs\">pieces</option></select></label></div><label>Price for that quantity (LKR)<input id=\"ingredientPrice\" type=\"number\" min=\"0.01\" max=\"1000000000\" step=\"0.01\" required placeholder=\"365.00\"></label><div class=\"expense-actions\"><button class=\"primary\" id=\"saveIngredient\">Save ingredient</button><button type=\"button\" id=\"cancelIngredient\" class=\"secondary\" hidden>Cancel edit</button></div></fieldset><p class=\"settings-note\" id=\"ingredientMessage\" role=\"status\"></p></form></section><section class=\"cost-card\"><h2 id=\"cakeCostHeading\">Cost for a saved invoice</h2><form id=\"cakeCostForm\"><fieldset id=\"cakeCostFields\"><label>Saved invoice<select id=\"cakeCostInvoice\" required><option value=\"\">Choose invoice number</option></select></label><label>Cake name <em>optional</em><input id=\"cakeCostName\" maxlength=\"100\" placeholder=\"Cake name from the selected invoice\"></label><div id=\"cakeCostLines\"></div><button type=\"button\" class=\"add\" id=\"addCostLine\">+ Add another ingredient</button><div class=\"cake-cost-total\"><span>TOTAL COST (LKR)</span><strong id=\"cakeCostTotal\">0.00</strong></div><button id=\"saveCakeCost\" class=\"primary\">Save cake costing</button></fieldset><p class=\"settings-note\" id=\"cakeCostMessage\" role=\"status\"></p></form></section></div></section></section><section id=\"customersPanel\" class=\"management-panel\" hidden><div class=\"history-top\"><h2>Customers</h2><input id=\"customerSearch\" type=\"search\" placeholder=\"Search name or phone\" aria-label=\"Search customers\"></div><p class=\"settings-note\">Customers are added when you save an invoice with a name and phone number.</p><p id=\"customersError\" class=\"management-error\" hidden role=\"alert\"></p><div id=\"customerRecords\"></div></section><section id=\"history\" hidden><div class=\"history-top\"><h2>Saved invoices</h2><input id=\"search\" placeholder=\"Search customer or invoice number\"></div><div id=\"records\"></div></section><footer class=\"app-footer\">Made with care. Just like your cakes. <span>JANANEE INVOICE STUDIO</span></footer></main><dialog id=\"cakeEditDialog\" class=\"cake-edit-dialog\"><div class=\"dialog-top\"><h2 id=\"cakeDialogTitle\">Add a cake</h2><button id=\"closeCakeEdit\" aria-label=\"Close cake editor\">×</button></div><form id=\"cakeEditForm\"><label class=\"photo-upload\"><img id=\"cakeImagePreview\" alt=\"Cake photo preview\" hidden><span id=\"uploadHint\">＋ Upload a cake photo</span><input id=\"cakeImageFile\" type=\"file\" accept=\"image/jpeg,image/png,image/webp\"><small>JPG, PNG or WebP · up to 5 MB</small></label><label>Cake title<input name=\"name\" required maxlength=\"100\"></label><label>Category<input name=\"category\" required maxlength=\"50\" list=\"cakeCategories\"><datalist id=\"cakeCategories\"></datalist></label><label>Description<textarea name=\"description\" rows=\"3\" maxlength=\"700\"></textarea></label><div class=\"grid\"><label>Display order<input name=\"sortOrder\" type=\"number\" min=\"0\" max=\"9999\" step=\"1\" required></label><div class=\"cake-checks\"><label><input type=\"checkbox\" name=\"active\"> Show on website</label><label><input type=\"checkbox\" name=\"featured\"> Featured cake</label></div></div><p id=\"cakeEditMessage\" class=\"management-error\" role=\"alert\" hidden></p><button class=\"primary\" id=\"saveCake\">Save cake</button></form></dialog><dialog id=\"accountDialog\"><div class=\"dialog-top\"><h2>Your account</h2><button id=\"closeAccount\" aria-label=\"Close account settings\">×</button></div><p id=\"accountEmail\"></p><h3>Change password</h3><form id=\"passwordForm\"><label>Current password<input id=\"currentPassword\" type=\"password\" autocomplete=\"current-password\" maxlength=\"128\" required></label><label>New password<input id=\"newPassword\" type=\"password\" autocomplete=\"new-password\" minlength=\"12\" maxlength=\"128\" required></label><label>Confirm new password<input id=\"repeatPassword\" type=\"password\" autocomplete=\"new-password\" minlength=\"12\" maxlength=\"128\" required></label><p id=\"passwordMessage\" role=\"status\"></p><button class=\"primary\" id=\"updatePassword\">Update password</button></form><p class=\"account-note\">Keep your recovery code safe. Use it on the login screen if you forget your password.</p></dialog><div id=\"loading\" class=\"loading\"><div><span class=\"loading-brand\">JANANEE</span><p id=\"loadingMessage\" role=\"status\">Opening your private invoice studio…</p><button id=\"retry\" class=\"secondary\" hidden>Reload</button></div></div><div id=\"toast\" role=\"status\"></div><script src=\"/app.js\"></script><script src=\"/admin.js\"></script><script type=\"module\" src=\"/costing-ui.js\"></script></body></html>\n"},"/login.html":{"type":"text/html; charset=utf-8","base64":false,"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Sign in · JANANEE Invoice Studio</title><link rel=\"stylesheet\" href=\"/auth.css\"></head><body><main class=\"auth-shell\"><section class=\"story\"><div class=\"wordmark\">JANANEE<span>CAKE SHOP</span></div><div class=\"story-copy\"><span class=\"eyebrow\">YOUR LITTLE BUSINESS, BEAUTIFULLY ORGANISED</span><h1>A sweet place<br>to get things done.</h1><p>Your orders, your invoices, your space.<br>Sign in and pick up where you left off.</p><div class=\"cake\">♡</div></div><footer>MADE WITH CARE. JUST LIKE YOUR CAKES.</footer></section><section class=\"form-side\"><div class=\"auth-card\"><a class=\"mobile-brand\" href=\"/\">JANANEE</a><div class=\"step\">SHOP ADMIN</div><h2 id=\"title\">Welcome back.</h2><p id=\"intro\">Checking your account…</p><a href=\"/signin-with-chatgpt?return_to=%2Fadmin%2Flogin\" target=\"_top\" id=\"ownerSetup\" class=\"submit owner-setup\" hidden>Verify shop owner →</a><div id=\"error\" role=\"alert\" hidden></div><form id=\"authForm\" hidden><label>Email address<input id=\"email\" type=\"email\" autocomplete=\"username\" maxlength=\"254\" required placeholder=\"you@example.com\"></label><label id=\"recoveryLabel\" hidden>Recovery code<input id=\"recoveryCode\" autocomplete=\"off\" maxlength=\"100\" placeholder=\"Your saved recovery code\"></label><label id=\"passwordLabel\">Password<div class=\"password-wrap\"><input id=\"password\" type=\"password\" autocomplete=\"current-password\" maxlength=\"128\" required placeholder=\"Enter your password\"><button type=\"button\" id=\"toggle\" aria-label=\"Show password\">Show</button></div></label><label id=\"confirmLabel\" hidden>Confirm password<input id=\"confirmPassword\" type=\"password\" autocomplete=\"new-password\" maxlength=\"128\"></label><p id=\"passwordHint\" hidden>Use at least 12 characters. A longer phrase is easier to remember.</p><button id=\"submit\" class=\"submit\" type=\"submit\">Sign in</button></form><button id=\"reset\" class=\"text-button\" hidden>Forgot password? Use recovery code</button><button id=\"back\" class=\"text-button\" hidden>Back to sign in</button><section id=\"recovery\" hidden><div class=\"recovery-icon\">✓</div><h3>Keep your recovery code safe.</h3><p>This code lets you reset your password. It is shown only once. Store it somewhere private.</p><code id=\"code\"></code><div class=\"recovery-actions\"><button id=\"copy\" type=\"button\">Copy code</button><button id=\"download\" type=\"button\">Download code</button></div><label class=\"ack\"><input id=\"ack\" type=\"checkbox\"> I have saved my recovery code</label><button id=\"continue\" class=\"submit\" disabled>Continue to admin panel →</button></section><div class=\"privacy\">For shop administrators only.<br>Looking for cakes? <a href=\"/\">Visit our cake gallery →</a></div><noscript>Please enable JavaScript to sign in.</noscript></div></section></main><script src=\"/auth.js\"></script></body></html>\n"},"/pink-rose-cake.jpg":{"type":"image/jpeg","base64":true,"content":""},"/style.css":{"type":"text/css; charset=utf-8","base64":false,"content":"@font-face{font-family:InvoiceSans;src:url('DejaVuSans.ttf')}@font-face{font-family:InvoiceSans;src:url('DejaVuSans-Bold.ttf');font-weight:700}@font-face{font-family:InvoiceSerif;src:url('DejaVuSerif.ttf')}*{box-sizing:border-box}body{margin:0;background:#f6f7f9;color:#152b44;font:13px Arial,sans-serif}button,input,textarea{font:inherit}button{cursor:pointer;border:0;border-radius:7px;padding:11px 15px;color:inherit;background:white}button:hover{filter:brightness(.96)}button:focus-visible,input:focus,textarea:focus{outline:2px solid #b99551;outline-offset:2px}aside{position:fixed;inset:0 auto 0 0;width:235px;background:#fff;border-right:1px solid #e6e9ed;padding:32px 22px;display:flex;flex-direction:column}.brand{display:flex;gap:12px;align-items:center;text-decoration:none;color:#b38b3c;font:35px Georgia}.brand span{font:18px Georgia;color:#142a43;letter-spacing:2px}.brand small{display:block;font:8px Arial;letter-spacing:1.1px;margin-top:8px;color:#8c929d}.nav-label{font-size:9px;letter-spacing:2px;color:#99a0ac;margin:52px 12px 15px}.nav{text-align:left;margin-bottom:8px;padding:14px 12px;font-size:12px}.nav.active{background:#f0f3f7;font-weight:bold}.nav span{float:right}.aside-bottom{margin-top:auto;padding:18px 8px 0;border-top:1px solid #eee;font-size:11px;color:#738095}.aside-bottom small{display:block;line-height:1.7;margin:12px 0}.aside-bottom button{font-size:10px;border:1px solid #e2e5eb;padding:8px;margin:3px 0}.dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#6c9d86;margin-right:5px}main{margin-left:235px;padding:40px 42px 20px;max-width:1800px}header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:33px}.eyebrow{font-size:9px;letter-spacing:2px;color:#a3854b}h1{font:29px Georgia;margin:12px 0}header p{color:#8190a0;font-size:12px}.secondary{border:1px solid #dce1e8;background:#fff}.primary{background:#152b44;color:white}.toolbar{display:flex;justify-content:space-between;align-items:center;padding:0 0 22px;font-size:11px;color:#7a8695}.toolbar button{margin-left:8px}.workspace{display:grid;grid-template-columns:minmax(300px,385px) minmax(350px,1fr);gap:32px;align-items:start}.panel{padding:25px;background:#fff;border:1px solid #e4e8ee;border-radius:10px}.section-title{display:flex;gap:11px;align-items:center;margin:5px 0 22px}.section-title:not(:first-child){margin-top:29px}.section-title span{font-size:10px;color:#aa8b50;background:#faf6ee;padding:7px;border-radius:50%}h2{font-size:14px;margin:0}label{display:block;color:#657183;font-size:10px;margin-bottom:15px}em{font-style:normal;color:#a1a8b3;font-size:9px;margin-left:5px}input,textarea{display:block;border:1px solid #dfe4eb;border-radius:5px;background:#fff;color:#20354e;padding:10px 11px;width:100%;margin-top:7px;line-height:1.4;resize:vertical}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.item{background:#f8f9fb;border:1px solid #e7eaf0;border-radius:6px;padding:14px;margin-bottom:12px}.item-top{display:flex;justify-content:space-between;align-items:center;font-size:10px;margin-bottom:14px}.remove{padding:3px 6px;background:transparent;color:#a97171}.item label:last-child{margin-bottom:0}.item .grid{grid-template-columns:70px 1fr}.add{border:1px dashed #cad2de;width:100%;background:white;color:#66758a;font-size:11px}summary{font-size:11px;cursor:pointer;padding:15px 0;color:#7e8896}details[open] summary{margin-bottom:10px}.preview-heading{display:flex;justify-content:space-between;color:#929ba8;font-size:9px;letter-spacing:1.5px;margin:5px 0 16px}.preview-heading span:last-child{letter-spacing:0}#preview{background:white;box-shadow:0 5px 25px #1a2e4210;line-height:0}#preview svg{width:100%;height:auto}.preview-area{max-width:710px;width:100%;margin:auto}.print-tip{font-size:10px;text-align:center;color:#929baa;margin:18px 0}.app-footer{font-size:10px;color:#9aa3ae;display:flex;justify-content:space-between;margin-top:35px;padding-top:20px;border-top:1px solid #e3e7ec}.app-footer span{font-size:8px;letter-spacing:1.5px}#toast{position:fixed;bottom:25px;left:50%;transform:translateX(-50%);padding:13px 22px;border-radius:7px;background:#152b44;color:white;opacity:0;pointer-events:none;transition:opacity .2s}#toast.show{opacity:1}.history-top{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:20px}.history-top input{max-width:320px}.record{display:flex;justify-content:space-between;align-items:center;padding:20px;background:white;border:1px solid #e2e6ed;border-radius:7px;margin:10px 0;gap:15px}.record small{display:block;color:#8b97a6;margin-top:7px}.record button{border:1px solid #e1e6ed;margin-left:6px}.empty{padding:60px;text-align:center;color:#8c98a8;background:white;border:1px dashed #dbe1e9}@media(min-width:1400px){.workspace{gap:50px}.preview-area{max-width:670px}}@media(max-width:1100px){aside{width:190px;padding:30px 15px}main{margin-left:190px;padding:30px 23px}.workspace{gap:20px;grid-template-columns:310px minmax(280px,1fr)}h1{font-size:25px}}@media(max-width:850px){aside{position:static;width:auto;padding:18px;display:flex;flex-direction:row;gap:10px;align-items:center;flex-wrap:wrap}.brand{margin-right:auto}.nav-label,.aside-bottom{display:none}.nav{margin:0;font-size:10px}main{margin:0;padding:25px 18px}.workspace{grid-template-columns:1fr}.preview-area{max-width:595px}header{align-items:flex-start}h1{font-size:24px}header .secondary{font-size:10px;white-space:nowrap}.app-footer span{display:none}}@media print{@page{size:A4;margin:0}html,body{background:#fff;margin:0;padding:0}aside,header,.toolbar,.panel,.preview-heading,.print-tip,.app-footer,#history,#toast{display:none!important}main{margin:0;padding:0;max-width:none}.workspace{display:block}.preview-area{margin:0;max-width:none;width:210mm}#preview{box-shadow:none}#preview svg{display:block;width:210mm;height:297mm;print-color-adjust:exact;-webkit-print-color-adjust:exact}}\n\nbutton:disabled{opacity:.5;cursor:wait}.loading{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;background:#f6f7f9;text-align:center;color:#8390a1}.loading-brand{font:34px Georgia;color:#172c46;letter-spacing:3px}.loading p{margin:25px 20px;max-width:400px;line-height:1.8}[hidden]{display:none!important}dialog{border:1px solid #e1e5eb;border-radius:12px;padding:28px;width:420px;max-width:calc(100vw - 30px);color:#172c46}dialog::backdrop{background:#10243d77}.dialog-top{display:flex;align-items:center;justify-content:space-between}.dialog-top button{padding:5px 10px;font-size:21px}#accountEmail{font-size:12px;color:#8b97a6;margin-bottom:25px}dialog h3{font-size:13px;margin-bottom:20px}#passwordMessage{font-size:12px;line-height:1.6;color:#9b7940}.account-note{font-size:11px;color:#8b97a6;line-height:1.7;border-top:1px solid #eee;padding-top:20px;margin-top:25px}@media print{dialog,.loading{display:none!important}}\n@media(max-width:850px){.aside-bottom{display:flex;flex-wrap:wrap;align-items:center;gap:5px;width:100%;border-top:1px solid #eee;padding:10px 0 0;margin:5px 0 0}.aside-bottom small{display:none}} #toast{max-width:90vw;line-height:1.7}\r\n"},"/yellow-swirl-cake.jpg":{"type":"image/jpeg","base64":true,"content":""}};
